window.PAGES = window.PAGES || {};
window.PAGES["day10-theory"] = {"title": "OCI Enterprise Governance, Cost, Security & Operations \u2014 Day 10 Capstone | Interactive Learning Platform", "css": "\n/* ============================================================\n   DESIGN TOKENS\n   Palette: void black base, Oracle red signal, cool blue for\n   network/data concepts, amber for warnings/exam-tips.\n   Type: Space Grotesk-style geometric display (system stack),\n   Inter-style body (system stack), JetBrains-style mono for\n   code/terminal (system stack) \u2014 no external fonts/CDNs.\n   ============================================================ */\n:host{\n  --void:#08090b;\n  --panel:#101217;\n  --panel-2:#15171e;\n  --panel-glass: rgba(21,23,30,0.6);\n  --border: rgba(255,255,255,0.08);\n  --border-strong: rgba(255,255,255,0.16);\n  --text-1:#eef0f3;\n  --text-2:#a7acb8;\n  --text-3:#6b7180;\n  --red:#c74634;\n  --red-bright:#ff5a3c;\n  --red-dim: rgba(199,70,52,0.15);\n  --blue:#4f8cff;\n  --blue-dim: rgba(79,140,255,0.15);\n  --amber:#e8a33d;\n  --amber-dim: rgba(232,163,61,0.15);\n  --green:#3ec28f;\n  --green-dim: rgba(62,194,143,0.15);\n  --radius: 14px;\n  --radius-sm: 8px;\n  --font-display: \"Space Grotesk\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-body: \"Inter\",\"Avenir Next\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;\n  --font-mono: \"JetBrains Mono\",\"SF Mono\",Consolas,\"Liberation Mono\",monospace;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.5);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.35);\n}\n:host([data-theme=\"light\"]){\n  --void:#f3f2ee;\n  --panel:#ffffff;\n  --panel-2:#f7f6f2;\n  --panel-glass: rgba(255,255,255,0.7);\n  --border: rgba(10,10,10,0.08);\n  --border-strong: rgba(10,10,10,0.16);\n  --text-1:#15171c;\n  --text-2:#4b4f58;\n  --text-3:#83879160;\n  --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);\n  --shadow-sm: 0 4px 16px rgba(0,0,0,0.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n@media (prefers-reduced-motion: reduce){\n  *{animation-duration:0.001ms !important; animation-iteration-count:1 !important; transition-duration:0.001ms !important;}\n}\n:host{scroll-behavior:smooth;}\n:host{\n  background:var(--void);\n  color:var(--text-1);\n  font-family:var(--font-body);\n  line-height:1.6;\n  -webkit-font-smoothing:antialiased;\n  overflow-x:hidden;\n  transition:background .4s ease,color .4s ease;\n}\nbody::before{\n  content:\"\";\n  position:fixed; inset:0; z-index:0; pointer-events:none;\n  background:\n    radial-gradient(ellipse 800px 500px at 15% -5%, rgba(199,70,52,0.16), transparent 60%),\n    radial-gradient(ellipse 700px 500px at 100% 20%, rgba(79,140,255,0.10), transparent 60%),\n    radial-gradient(ellipse 600px 400px at 50% 100%, rgba(199,70,52,0.08), transparent 60%);\n}\nh1,h2,h3,h4{font-family:var(--font-display); letter-spacing:-0.02em; font-weight:700; color:var(--text-1);}\ncode, .mono{font-family:var(--font-mono);}\na{color:inherit;}\n::selection{background:var(--red); color:#fff;}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border-strong); border-radius:10px;}\n\n/* ---------- particles / ambient bg ---------- */\n#particles{position:fixed; inset:0; z-index:0; pointer-events:none; opacity:.5;}\n\n/* ---------- progress bar ---------- */\n#progress-bar{\n  position:fixed; top:0; left:0; height:3px; width:0%;\n  background:linear-gradient(90deg,var(--red),var(--red-bright));\n  z-index:9999; box-shadow:0 0 12px var(--red-bright);\n  transition:width .1s linear;\n}\n\n/* ---------- top bar ---------- */\n#topbar{\n  position:fixed; top:0; left:0; right:0; z-index:900;\n  height:60px; display:flex; align-items:center; gap:14px;\n  padding:0 18px; margin-top:3px;\n  background:var(--panel-glass); backdrop-filter:blur(16px) saturate(140%);\n  border-bottom:1px solid var(--border);\n}\n#topbar .brand{display:flex; align-items:center; gap:10px; font-family:var(--font-display); font-weight:700; font-size:15px; white-space:nowrap;}\n#topbar .brand .dot{width:10px; height:10px; border-radius:3px; background:linear-gradient(135deg,var(--red),var(--red-bright)); box-shadow:0 0 14px var(--red-bright);}\n#sidebar-toggle{\n  background:transparent; border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:var(--radius-sm); cursor:pointer; font-size:16px;\n  display:flex; align-items:center; justify-content:center; transition:.2s;\n}\n#sidebar-toggle:hover{border-color:var(--border-strong); color:var(--text-1);}\n#search-wrap{position:relative; flex:1; max-width:420px;}\n#search{\n  width:100%; background:var(--panel); border:1px solid var(--border); color:var(--text-1);\n  padding:8px 14px 8px 34px; border-radius:999px; font-size:13px; font-family:var(--font-body);\n  outline:none; transition:.2s;\n}\n#search:focus{border-color:var(--red); box-shadow:0 0 0 3px var(--red-dim);}\n#search-wrap svg{position:absolute; left:12px; top:50%; transform:translateY(-50%); width:14px; height:14px; color:var(--text-3);}\n#search-results{\n  position:absolute; top:calc(100% + 8px); left:0; right:0; background:var(--panel);\n  border:1px solid var(--border-strong); border-radius:var(--radius-sm); box-shadow:var(--shadow-lg);\n  max-height:320px; overflow-y:auto; display:none; z-index:50;\n}\n#search-results a{display:block; padding:9px 14px; font-size:13px; color:var(--text-2); border-bottom:1px solid var(--border);}\n#search-results a:hover{background:var(--panel-2); color:var(--text-1);}\n#search-results .sr-cat{font-size:10px; text-transform:uppercase; letter-spacing:.08em; color:var(--red-bright); display:block; margin-bottom:2px;}\n\n.topbar-spacer{flex:1;}\n#theme-toggle{\n  background:var(--panel); border:1px solid var(--border); color:var(--text-2);\n  width:36px; height:36px; border-radius:999px; cursor:pointer; display:flex; align-items:center; justify-content:center;\n  transition:.2s; font-size:15px;\n}\n#theme-toggle:hover{border-color:var(--red); color:var(--red-bright);}\n#score-chip{\n  display:flex; align-items:center; gap:6px; background:var(--panel); border:1px solid var(--border);\n  padding:6px 12px; border-radius:999px; font-size:12px; color:var(--text-2); white-space:nowrap;\n}\n#score-chip b{color:var(--red-bright); font-family:var(--font-display);}\n\n/* ---------- layout ---------- */\n#shell{display:flex; padding-top:63px; position:relative; z-index:1;}\n#sidebar{\n  width:270px; flex-shrink:0; height:calc(100% - 63px); position:sticky; top:63px;\n  overflow-y:auto; border-right:1px solid var(--border); padding:18px 10px 60px;\n  transition:margin-left .3s ease, opacity .3s ease;\n}\n#sidebar.collapsed{margin-left:-270px; opacity:0;}\n#sidebar .nav-group{margin-bottom:4px;}\n#sidebar .nav-head{\n  font-size:10px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);\n  padding:14px 12px 6px; font-weight:700;\n}\n#sidebar a.nav-link{\n  display:flex; align-items:center; gap:9px; padding:8px 12px; border-radius:var(--radius-sm);\n  font-size:13.5px; color:var(--text-2); text-decoration:none; transition:.15s; border-left:2px solid transparent;\n}\n#sidebar a.nav-link:hover{background:var(--panel); color:var(--text-1);}\n#sidebar a.nav-link.active{background:var(--red-dim); color:var(--red-bright); border-left-color:var(--red-bright); font-weight:600;}\n#sidebar a.nav-link .num{font-family:var(--font-mono); font-size:10px; color:var(--text-3); width:18px;}\n\nmain{flex:1; min-width:0; padding:0 0 100px;}\n.container{max-width:980px; margin:0 auto; padding:0 32px;}\n\n/* ---------- hero ---------- */\n#hero{position:relative; padding:100px 32px 70px; overflow:hidden; text-align:left;}\n#hero .eyebrow{\n  display:inline-flex; align-items:center; gap:8px; font-size:12px; letter-spacing:.1em; text-transform:uppercase;\n  color:var(--red-bright); background:var(--red-dim); border:1px solid rgba(199,70,52,0.3);\n  padding:6px 14px; border-radius:999px; margin-bottom:22px; font-weight:600;\n}\n#hero h1{font-size:clamp(2.4rem,5vw,4.2rem); line-height:1.02; max-width:820px;}\n#hero h1 .accent{background:linear-gradient(135deg,var(--red),var(--red-bright)); -webkit-background-clip:text; background-clip:text; color:transparent;}\n#hero p.lede{max-width:620px; font-size:17px; color:var(--text-2); margin-top:22px;}\n#hero .hero-stats{display:flex; gap:34px; margin-top:40px; flex-wrap:wrap;}\n#hero .hstat b{font-family:var(--font-display); font-size:26px; display:block;}\n#hero .hstat span{font-size:12px; color:var(--text-3); text-transform:uppercase; letter-spacing:.06em;}\n#hero .cta-row{display:flex; gap:14px; margin-top:38px; flex-wrap:wrap;}\n.btn{\n  font-family:var(--font-body); font-weight:600; font-size:14px; padding:12px 22px; border-radius:999px;\n  border:1px solid var(--border-strong); cursor:pointer; transition:.2s; display:inline-flex; align-items:center; gap:8px;\n}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-bright)); color:#fff; border:none; box-shadow:0 8px 24px rgba(199,70,52,0.35);}\n.btn-primary:hover{transform:translateY(-2px); box-shadow:0 12px 30px rgba(199,70,52,0.45);}\n.btn-ghost{background:var(--panel); color:var(--text-1);}\n.btn-ghost:hover{border-color:var(--red); color:var(--red-bright);}\n\n/* orbiting node animation in hero */\n#hero-orbit{position:absolute; right:-60px; top:40px; width:420px; height:420px; opacity:.9; pointer-events:none;}\n@media (max-width:1100px){#hero-orbit{display:none;}}\n\n/* ---------- sections ---------- */\nsection.chapter{padding:70px 0 10px; border-top:1px solid var(--border); scroll-margin-top:80px;}\nsection.chapter:first-of-type{border-top:none;}\n.chapter-kicker{display:flex; align-items:center; gap:10px; margin-bottom:14px;}\n.chapter-kicker .idx{\n  font-family:var(--font-mono); font-size:12px; color:var(--red-bright); background:var(--red-dim);\n  padding:4px 10px; border-radius:6px; border:1px solid rgba(199,70,52,.3);\n}\n.chapter-kicker .track{font-size:11px; text-transform:uppercase; letter-spacing:.1em; color:var(--text-3);}\n.chapter h2{font-size:clamp(1.6rem,3vw,2.3rem); margin-bottom:6px;}\n.chapter .dek{color:var(--text-2); font-size:15.5px; max-width:680px; margin-bottom:30px;}\n.chapter h3{font-size:1.15rem; margin:34px 0 14px;}\n.chapter p{color:var(--text-2); font-size:15px; margin-bottom:14px; max-width:720px;}\n.chapter ul, .chapter ol{color:var(--text-2); font-size:15px; margin:0 0 16px 20px;}\n.chapter li{margin-bottom:6px;}\n.chapter strong{color:var(--text-1);}\n\n/* scroll reveal */\n.reveal{opacity:0; transform:translateY(24px); transition:opacity .7s ease, transform .7s ease;}\n.reveal.in{opacity:1; transform:translateY(0);}\n\n/* ---------- cards / panels ---------- */\n.panel{\n  background:linear-gradient(180deg,var(--panel),var(--panel-2));\n  border:1px solid var(--border); border-radius:var(--radius); padding:24px;\n  box-shadow:var(--shadow-sm); position:relative;\n}\n.panel-glow{position:relative; overflow:hidden;}\n.panel-glow::before{\n  content:\"\"; position:absolute; inset:-2px; z-index:-1; border-radius:inherit;\n  background:conic-gradient(from 180deg, var(--red), transparent 30%, var(--blue), transparent 70%, var(--red));\n  opacity:0; transition:opacity .4s;\n}\n.panel-glow:hover::before{opacity:.5;}\n.panel-glow > .panel-inner{background:var(--panel); border-radius:calc(var(--radius) - 1px); height:100%; padding:22px;}\n\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;}\n.grid-3{grid-template-columns:repeat(3,1fr);}\n.grid-4{grid-template-columns:repeat(4,1fr);}\n@media (max-width:800px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr;}}\n\n.card{\n  background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm);\n  padding:18px; transition:.25s; cursor:default;\n}\n.card:hover{border-color:var(--border-strong); transform:translateY(-3px); box-shadow:var(--shadow-sm);}\n.card h4{font-size:14px; margin-bottom:8px; display:flex; align-items:center; gap:8px;}\n.card p{font-size:13.5px; margin:0; color:var(--text-2);}\n.card .tag{font-size:10px; text-transform:uppercase; letter-spacing:.06em; color:var(--red-bright); background:var(--red-dim); padding:3px 8px; border-radius:6px; margin-bottom:8px; display:inline-block;}\n\n/* ---------- callouts ---------- */\n.callout{border-radius:var(--radius-sm); padding:14px 16px; margin:16px 0; border:1px solid; font-size:14px; display:flex; gap:12px; align-items:flex-start;}\n.callout .ic{font-size:16px; flex-shrink:0; margin-top:1px;}\n.callout-tip{background:var(--green-dim); border-color:rgba(62,194,143,.35); color:var(--text-1);}\n.callout-warn{background:var(--amber-dim); border-color:rgba(232,163,61,.35); color:var(--text-1);}\n.callout-trap{background:var(--red-dim); border-color:rgba(199,70,52,.35); color:var(--text-1);}\n.callout-q{background:var(--blue-dim); border-color:rgba(79,140,255,.35); color:var(--text-1);}\n.callout b{display:block; font-size:11px; text-transform:uppercase; letter-spacing:.06em; margin-bottom:3px;}\n\n/* ---------- tables ---------- */\ntable.cmp{width:100%; border-collapse:collapse; font-size:13.5px; margin:18px 0;}\ntable.cmp th{text-align:left; color:var(--text-3); font-size:11px; text-transform:uppercase; letter-spacing:.06em; padding:10px 12px; border-bottom:1px solid var(--border-strong);}\ntable.cmp td{padding:12px; border-bottom:1px solid var(--border); color:var(--text-2);}\ntable.cmp tr:hover td{background:var(--panel);}\ntable.cmp td:first-child, table.cmp th:first-child{color:var(--text-1); font-weight:600;}\n\n/* ---------- buttons small ---------- */\n.chip-btn{\n  background:var(--panel-2); border:1px solid var(--border); color:var(--text-2); font-size:12.5px;\n  padding:7px 14px; border-radius:999px; cursor:pointer; transition:.2s; font-family:var(--font-body); font-weight:600;\n}\n.chip-btn:hover{border-color:var(--red); color:var(--red-bright);}\n.chip-btn.active{background:var(--red); color:#fff; border-color:var(--red);}\n.chip-btn:disabled{opacity:.4; cursor:not-allowed;}\n\n/* end of part1 */\n\n\n.vm-sim{display:grid; grid-template-columns:280px 1fr; gap:20px;}\n@media (max-width:800px){.vm-sim{grid-template-columns:1fr;}}\n.vm-controls{display:flex; flex-direction:column; gap:10px;}\n.vm-controls label{font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--text-3); margin-top:6px;}\n.vm-controls input[type=range]{width:100%; accent-color:var(--red);}\n.host-box{border:1px dashed var(--border-strong); border-radius:var(--radius-sm); padding:16px; position:relative; background:repeating-linear-gradient(135deg, rgba(255,255,255,0.015) 0 10px, transparent 10px 20px);}\n.host-meter{display:flex; justify-content:space-between; font-size:11px; color:var(--text-3); margin-bottom:6px;}\n.meter-bar{height:8px; border-radius:6px; background:var(--panel-2); overflow:hidden; margin-bottom:14px;}\n.meter-fill{height:100%; border-radius:6px; transition:width .4s ease; background:linear-gradient(90deg,var(--blue),#7db2ff);}\n.meter-fill.cpu{background:linear-gradient(90deg,var(--red),var(--red-bright));}\n.vm-list{display:flex; flex-wrap:wrap; gap:10px; min-height:60px;}\n.vm-card{width:110px; background:var(--panel); border:1px solid var(--border-strong); border-radius:10px; padding:10px; font-size:11px; animation:popIn .3s ease; position:relative;}\n.vm-card .vm-name{font-family:var(--font-mono); color:var(--blue); font-weight:700; margin-bottom:4px;}\n.vm-card .vm-x{position:absolute; top:6px; right:8px; cursor:pointer; color:var(--text-3);}\n.vm-card .vm-x:hover{color:var(--red-bright);}\n@keyframes popIn{from{opacity:0; transform:scale(.7);} to{opacity:1; transform:scale(1);}}\n.layer-stack{display:flex; flex-direction:column; gap:6px;}\n.layer-row{display:grid; grid-template-columns:130px 1fr; gap:0; border-radius:var(--radius-sm); overflow:hidden; border:1px solid var(--border);}\n.layer-label{background:var(--panel-2); display:flex; align-items:center; justify-content:center; font-family:var(--font-display); font-weight:700; font-size:13px;}\n.layer-cells{display:grid; grid-template-columns:repeat(6,1fr);}\n.layer-cell{padding:12px 6px; text-align:center; font-size:11px; border-left:1px solid var(--border); transition:.2s; cursor:default;}\n.layer-cell.you{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.layer-cell.oracle{background:var(--blue-dim); color:var(--blue); font-weight:700;}\n.layer-cell:hover{filter:brightness(1.3);}\n.layer-legend{display:flex; gap:18px; margin-top:12px; font-size:12px; color:var(--text-2);}\n.legend-dot{width:10px; height:10px; border-radius:3px; display:inline-block; margin-right:6px; vertical-align:-1px;}\n.resp-track{position:relative; height:10px; border-radius:6px; background:linear-gradient(90deg,var(--blue) 0%,var(--blue) var(--split,50%), var(--red) var(--split,50%), var(--red) 100%); margin:30px 0 10px;}\n.resp-handle{position:absolute; top:50%; left:var(--split,50%); transform:translate(-50%,-50%); width:26px; height:26px; border-radius:50%; background:#fff; border:3px solid var(--void); cursor:grab; box-shadow:0 0 0 4px rgba(255,255,255,0.15);}\n.resp-labels{display:flex; justify-content:space-between; font-size:12px; color:var(--text-2); margin-bottom:4px;}\n.resp-layers{display:flex; flex-direction:column; gap:8px; margin-top:20px;}\n.resp-layer-row{display:flex; align-items:center; gap:12px; font-size:13px;}\n.resp-layer-row .name{width:150px; flex-shrink:0; color:var(--text-1); font-weight:600;}\n.resp-layer-row .who{font-family:var(--font-mono); font-size:11px; padding:4px 10px; border-radius:6px;}\n.who-oracle{background:var(--blue-dim); color:var(--blue);}\n.who-you{background:var(--red-dim); color:var(--red-bright);}\n.who-shared{background:var(--amber-dim); color:var(--amber);}\n.map-wrap{display:grid; grid-template-columns:1fr 260px; gap:20px;}\n@media (max-width:800px){.map-wrap{grid-template-columns:1fr;}}\n.region-dot{cursor:pointer; transition:.2s;}\n.region-dot circle{transition:.2s;}\n.region-info{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:16px; font-size:13px; min-height:180px;}\n.region-info h4{font-size:14px; color:var(--red-bright); margin-bottom:8px;}\n.region-info .placeholder{color:var(--text-3); font-style:italic;}\n.ad-buildings{display:flex; gap:16px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.building{width:120px; text-align:center; padding:16px 10px; border-radius:var(--radius-sm); border:1px solid var(--border-strong); background:var(--panel); transition:.4s;}\n.building .roof{font-size:26px; margin-bottom:6px;}\n.building .b-name{font-family:var(--font-mono); font-size:12px; margin-bottom:4px;}\n.building .b-status{font-size:11px; padding:3px 8px; border-radius:6px; display:inline-block;}\n.b-status.ok{background:var(--green-dim); color:var(--green);}\n.b-status.down{background:var(--red-dim); color:var(--red-bright);}\n.building.failed{opacity:.4; filter:grayscale(1); transform:translateY(4px);}\n.building.shaking{animation:shake .4s;}\n@keyframes shake{0%,100%{transform:translateX(0);}25%{transform:translateX(-4px);}75%{transform:translateX(4px);}}\n.fd-rack{display:flex; gap:14px; justify-content:center; margin:20px 0; flex-wrap:wrap;}\n.rack{width:150px; border:1px solid var(--border-strong); border-radius:8px; padding:8px; background:var(--panel);}\n.rack .rack-head{font-family:var(--font-mono); font-size:11px; text-align:center; color:var(--text-3); margin-bottom:6px;}\n.rack-slot{height:20px; border-radius:4px; background:var(--panel-2); margin-bottom:4px; font-size:9px; display:flex; align-items:center; justify-content:center; color:var(--text-3); border:1px solid var(--border);}\n.rack-slot.filled{background:var(--blue-dim); color:var(--blue); border-color:rgba(79,140,255,.4); font-weight:700;}\n.rack.dead{opacity:.35;}\n.rack.dead .rack-slot.filled{background:var(--red-dim); color:var(--red-bright);}\n.calc-grid{display:grid; grid-template-columns:1fr 1fr; gap:24px;}\n@media (max-width:800px){.calc-grid{grid-template-columns:1fr;}}\n.calc-row{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:14px;}\n.calc-row label{font-size:13px; color:var(--text-2);}\n.calc-row output{font-family:var(--font-mono); color:var(--red-bright); font-weight:700; font-size:13px;}\ncanvas#capexChart{width:100%; height:220px;}\n.cost-total{display:flex; justify-content:space-between; padding-top:14px; border-top:1px solid var(--border); margin-top:6px;}\n.cost-total b{font-family:var(--font-display); font-size:20px;}\n.policy-editor{background:#0c0d10; border:1px solid var(--border-strong); border-radius:var(--radius-sm); padding:16px; font-family:var(--font-mono); font-size:13.5px;}\n.policy-editor textarea{width:100%; min-height:80px; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:13.5px; resize:vertical; line-height:1.7;}\n.policy-verdict{margin-top:10px; padding:10px 12px; border-radius:8px; font-size:12.5px; font-family:var(--font-body); display:none;}\n.policy-verdict.ok{display:block; background:var(--green-dim); color:var(--green);}\n.policy-verdict.bad{display:block; background:var(--red-dim); color:var(--red-bright);}\n.console-sim{border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden; background:var(--panel);}\n.console-tb{display:flex; align-items:center; gap:10px; background:var(--panel-2); padding:10px 14px; border-bottom:1px solid var(--border);}\n.console-tb .dots span{width:10px; height:10px; border-radius:50%; display:inline-block; margin-right:5px;}\n.console-body{display:flex; min-height:320px;}\n.console-nav{width:170px; border-right:1px solid var(--border); padding:12px 8px; flex-shrink:0;}\n.console-nav div{padding:8px 10px; font-size:12.5px; border-radius:6px; cursor:pointer; color:var(--text-2); margin-bottom:2px;}\n.console-nav div.active{background:var(--red-dim); color:var(--red-bright); font-weight:700;}\n.console-main{flex:1; padding:16px;}\n.console-toolbar{display:flex; gap:8px; margin-bottom:14px;}\n.console-table{width:100%; font-size:12.5px; border-collapse:collapse;}\n.console-table th{text-align:left; font-size:10px; text-transform:uppercase; color:var(--text-3); padding:6px 8px; border-bottom:1px solid var(--border-strong);}\n.console-table td{padding:8px; border-bottom:1px solid var(--border); color:var(--text-2);}\n.console-table tr:hover td{background:var(--panel-2);}\n.status-pill{font-size:10px; padding:2px 8px; border-radius:20px;}\n.status-pill.active{background:var(--green-dim); color:var(--green);}\n.status-pill.deleted{background:var(--red-dim); color:var(--red-bright);}\n.mini-input{background:var(--panel-2); border:1px solid var(--border-strong); color:var(--text-1); border-radius:6px; padding:6px 10px; font-size:12.5px; font-family:var(--font-body);}\n.terminal{background:#0a0b0d; border:1px solid var(--border-strong); border-radius:var(--radius); overflow:hidden;}\n.terminal-tb{background:#16171c; padding:8px 14px; font-size:11px; color:var(--text-3); font-family:var(--font-mono); border-bottom:1px solid var(--border);}\n#term-out{padding:16px; font-family:var(--font-mono); font-size:12.5px; color:#c9f7d8; height:280px; overflow-y:auto; white-space:pre-wrap;}\n#term-out .cmdline{color:#7db2ff;}\n#term-out .cmdline::before{content:\"$ \"; color:var(--red-bright);}\n.term-input-row{display:flex; align-items:center; gap:8px; padding:10px 16px; border-top:1px solid var(--border); font-family:var(--font-mono); font-size:12.5px;}\n.term-input-row span{color:var(--red-bright);}\n#term-input{flex:1; background:transparent; border:none; outline:none; color:#e8e8ea; font-family:var(--font-mono); font-size:12.5px;}\n.tree{font-size:13.5px;}\n.tree ul{list-style:none; margin-left:22px; border-left:1px dashed var(--border-strong); padding-left:18px;}\n.tree li{margin:6px 0; position:relative;}\n.tree .node{display:inline-flex; align-items:center; gap:6px; padding:5px 10px; border-radius:6px; cursor:pointer; transition:.15s;}\n.tree .node:hover{background:var(--panel-2);}\n.tree .node .ic{font-size:13px;}\n.tree .node.root{color:var(--red-bright); font-weight:700;}\n.flash-wrap{display:grid; grid-template-columns:repeat(3,1fr); gap:16px;}\n@media (max-width:800px){.flash-wrap{grid-template-columns:1fr 1fr;}}\n@media (max-width:520px){.flash-wrap{grid-template-columns:1fr;}}\n.flashcard{perspective:1000px; height:130px; cursor:pointer;}\n.flashcard .fc-inner{position:relative; width:100%; height:100%; transition:transform .5s; transform-style:preserve-3d;}\n.flashcard.flipped .fc-inner{transform:rotateY(180deg);}\n.fc-face{position:absolute; inset:0; backface-visibility:hidden; border-radius:var(--radius-sm); border:1px solid var(--border-strong); padding:14px; display:flex; align-items:center; justify-content:center; text-align:center; font-size:13px;}\n.fc-front{background:var(--panel);}\n.fc-back{background:var(--red-dim); color:var(--red-bright); transform:rotateY(180deg); font-weight:600;}\n.quiz-q{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius-sm); padding:18px 20px; margin-bottom:14px;}\n.quiz-q .qtext{font-size:14.5px; font-weight:600; margin-bottom:12px;}\n.quiz-opts{display:flex; flex-direction:column; gap:8px;}\n.quiz-opt{display:flex; align-items:center; gap:10px; padding:10px 14px; border-radius:8px; border:1px solid var(--border); cursor:pointer; font-size:13.5px; color:var(--text-2); transition:.15s;}\n.quiz-opt:hover{border-color:var(--border-strong); background:var(--panel-2);}\n.quiz-opt input{accent-color:var(--red);}\n.quiz-opt.correct{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n.quiz-opt.incorrect{border-color:var(--red); background:var(--red-dim); color:var(--red-bright);}\n.quiz-explain{font-size:12.5px; color:var(--text-3); margin-top:10px; display:none; padding-top:10px; border-top:1px dashed var(--border);}\n.quiz-q.answered .quiz-explain{display:block;}\n#badge-wrap{text-align:center; padding:60px 20px;}\n.badge-circle{width:150px; height:150px; border-radius:50%; margin:0 auto 20px; position:relative; background:conic-gradient(var(--red-bright) 0deg, var(--red) var(--pct,0deg), var(--panel-2) var(--pct,0deg)); display:flex; align-items:center; justify-content:center; transition:background 1s ease;}\n.badge-circle::before{content:\"\"; position:absolute; inset:10px; border-radius:50%; background:var(--void);}\n.badge-circle span{position:relative; font-family:var(--font-display); font-size:28px; font-weight:700;}\n.center{text-align:center;}\n.mt-lg{margin-top:36px;}\n.small{font-size:12px; color:var(--text-3);}\nfooter{text-align:center; padding:50px 20px; color:var(--text-3); font-size:12.5px; border-top:1px solid var(--border); margin-top:60px;}\n.toc-jump{display:flex; gap:8px; flex-wrap:wrap; margin-top:18px;}\n\n\n/* ============================================================\n   DAY 10 \u2014 CAPSTONE WIDGET STYLES\n   (tenancy designer, policy builder, tagging validator, org\n   hierarchy, landing zone builder, cost dashboards, idle\n   resource detector, security posture/gap analyzer, compliance\n   matrix, architecture studio, executive dashboards, mock exam)\n   ============================================================ */\n\n/* --- score rings (reused pattern, multiple on one dashboard) --- */\n.score-ring-sm{width:90px; height:90px; border-radius:50%; position:relative; background:conic-gradient(var(--ring-color,var(--green)) calc(var(--s,0)*3.6deg), var(--panel-2) 0); margin:0 auto; transition:background .6s ease;}\n.score-ring-sm::before{content:\"\"; position:absolute; inset:7px; border-radius:50%; background:var(--panel);}\n.score-ring-sm span{position:relative; display:flex; align-items:center; justify-content:center; height:100%; font-family:var(--font-display); font-size:17px; font-weight:700;}\n.score-kpi{text-align:center;}\n.score-kpi .k-label{font-size:10.5px; text-transform:uppercase; color:var(--text-3); letter-spacing:.05em; margin-top:8px;}\n\n/* --- tenancy designer --- */\n.td-canvas{border:1px dashed var(--border-strong); border-radius:var(--radius); padding:16px; min-height:200px;}\n.td-tree .tree{font-size:13px;}\n\n/* --- policy designer --- */\n.policy-scenarios{display:flex; flex-wrap:wrap; gap:8px; margin-top:10px;}\n\n/* --- tagging strategy --- */\n.tag-namespace-row{display:flex; gap:8px; align-items:center; margin-bottom:8px; flex-wrap:wrap;}\n.tag-pill{font-size:11px; background:var(--panel-2); border:1px solid var(--border-strong); padding:4px 10px; border-radius:20px;}\n\n/* --- org hierarchy / multi-tenancy --- */\n.org-canvas{display:flex; flex-direction:column; align-items:center; gap:8px;}\n.org-parent-box{border:2px solid var(--red); border-radius:10px; padding:14px 24px; text-align:center; font-size:13px;}\n.org-children-row{display:flex; gap:14px; flex-wrap:wrap; justify-content:center; margin-top:10px;}\n.org-child-box{border:1px solid var(--border-strong); border-radius:8px; padding:10px 16px; font-size:12px; background:var(--panel);}\n\n/* --- landing zone builder --- */\n.lz-layer-row{display:flex; align-items:center; justify-content:space-between; padding:12px 16px; border:1px solid var(--border); border-radius:8px; margin-bottom:8px; font-size:13px;}\n.lz-layer-row .lz-status{font-size:10px; padding:2px 10px; border-radius:20px;}\n.lz-status.configured{background:var(--green-dim); color:var(--green);}\n.lz-status.pending{background:var(--amber-dim); color:var(--amber);}\n\n/* --- idle resource detector --- */\n.idle-item{display:flex; justify-content:space-between; align-items:center; padding:10px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:6px; font-size:13px;}\n.idle-item.cleaned{opacity:.4; text-decoration:line-through;}\n.savings-counter{font-family:var(--font-display); font-size:26px; color:var(--green);}\n\n/* --- security gap analyzer --- */\n.gap-item{display:flex; justify-content:space-between; align-items:center; padding:12px 14px; border:1px solid var(--border); border-radius:8px; margin-bottom:8px; font-size:13px;}\n.gap-item.fixed{border-color:var(--green); background:var(--green-dim);}\n.gap-severity{font-size:10px; padding:2px 10px; border-radius:20px;}\n\n/* --- architecture design studio --- */\n.studio-layer-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(140px,1fr)); gap:8px;}\n.studio-component{background:var(--panel); border:1px solid var(--border); border-radius:8px; padding:10px; text-align:center; font-size:11.5px; cursor:pointer; transition:.2s;}\n.studio-component.added{border-color:var(--green); background:var(--green-dim); color:var(--green);}\n\n/* --- operations center --- */\n.opscenter-tabs{display:flex; gap:6px; flex-wrap:wrap; margin-bottom:12px;}\n.opscenter-tabs button.chip-btn.done{border-color:var(--green); color:var(--green);}\n\n/* --- executive dashboard --- */\n.exec-grid{display:grid; grid-template-columns:repeat(4,1fr); gap:16px;}\n@media (max-width:900px){.exec-grid{grid-template-columns:1fr 1fr;}}\n.exec-overall{text-align:center; padding:24px; grid-column:1/-1; border:1px solid var(--border-strong); border-radius:var(--radius); background:linear-gradient(180deg,var(--panel),var(--panel-2));}\n\n/* --- comprehensive lab checklist --- */\n.enterprise-lab-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:10px;}\n\n/* --- mock exam --- */\n.domain-bar-row{display:flex; align-items:center; gap:10px; margin-bottom:8px; font-size:12.5px;}\n.domain-bar-row .domain-name{width:170px; flex-shrink:0;}\n.domain-bar-track{flex:1; height:10px; border-radius:6px; background:var(--panel-2); overflow:hidden;}\n.domain-bar-fill{height:100%; background:linear-gradient(90deg,var(--red),var(--red-bright));}\n\n", "html": "\nHTMLEOF\nwc -l head.html<canvas id=\"particles\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"topbar\">\n  <button id=\"sidebar-toggle\" title=\"Toggle sidebar\">\u2630</button>\n  <div class=\"brand\"><span class=\"dot\"></span> OCI Enterprise Governance, Cost, Security &amp; Ops \u00b7 Day 10 Capstone</div>\n  <div id=\"search-wrap\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n    <input id=\"search\" type=\"text\" placeholder=\"Search governance, cost, security, compliance\u2026\" autocomplete=\"off\">\n    <div id=\"search-results\"></div>\n  </div>\n  <div class=\"topbar-spacer\"></div>\n  <div id=\"score-chip\">Quiz score: <b id=\"score-chip-val\">0/0</b></div>\n  <button id=\"theme-toggle\" title=\"Toggle theme\">\ud83c\udf19</button>\n</div>\n<div id=\"shell\">\n  <nav id=\"sidebar\">\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 1 \u00b7 Enterprise Governance</div>\n      <a class=\"nav-link\" href=\"#sec-governance-review\"><span class=\"num\">01</span>Governance Review</a>\n      <a class=\"nav-link\" href=\"#sec-tenancydesigner\"><span class=\"num\">02</span>Enterprise Tenancy Designer</a>\n      <a class=\"nav-link\" href=\"#sec-governancechecklist\"><span class=\"num\">03</span>Governance Checklist</a>\n      <a class=\"nav-link\" href=\"#sec-policydesigner\"><span class=\"num\">04</span>Policy Designer</a>\n      <a class=\"nav-link\" href=\"#sec-taggingstrategy\"><span class=\"num\">05</span>Tagging Strategy</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 2 \u00b7 Organization Mgmt</div>\n      <a class=\"nav-link\" href=\"#sec-orgmgmt\"><span class=\"num\">06</span>Organization Management</a>\n      <a class=\"nav-link\" href=\"#sec-multitenancy\"><span class=\"num\">07</span>Multi-Tenancy Designer</a>\n      <a class=\"nav-link\" href=\"#sec-landingzone\"><span class=\"num\">08</span>Landing Zone Design</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 3 \u00b7 Cost Optimization</div>\n      <a class=\"nav-link\" href=\"#sec-costanalysis\"><span class=\"num\">09</span>Cost Analysis Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-rightsizing\"><span class=\"num\">10</span>Right Sizing</a>\n      <a class=\"nav-link\" href=\"#sec-idledetector\"><span class=\"num\">11</span>Idle Resource Detector</a>\n      <a class=\"nav-link\" href=\"#sec-commitmentdiscounts\"><span class=\"num\">12</span>Commitment Discounts</a>\n      <a class=\"nav-link\" href=\"#sec-finopsdash\"><span class=\"num\">13</span>FinOps Dashboard</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 4 \u00b7 Security Posture</div>\n      <a class=\"nav-link\" href=\"#sec-securityposture\"><span class=\"num\">14</span>Security Posture Review</a>\n      <a class=\"nav-link\" href=\"#sec-securitygap\"><span class=\"num\">15</span>Security Gap Analyzer</a>\n      <a class=\"nav-link\" href=\"#sec-remediation\"><span class=\"num\">16</span>Remediation Planner</a>\n      <a class=\"nav-link\" href=\"#sec-patchbackup\"><span class=\"num\">17</span>Patch Mgmt &amp; Backup Validation</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 5 \u00b7 Compliance</div>\n      <a class=\"nav-link\" href=\"#sec-compliancematrix\"><span class=\"num\">18</span>Compliance Matrix</a>\n      <a class=\"nav-link\" href=\"#sec-auditreadiness\"><span class=\"num\">19</span>Audit Readiness</a>\n      <a class=\"nav-link\" href=\"#sec-compliancereport\"><span class=\"num\">20</span>Compliance Report</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 6 \u00b7 Case Study</div>\n      <a class=\"nav-link\" href=\"#sec-casestudy\"><span class=\"num\">21</span>Banking Platform Case Study</a>\n      <a class=\"nav-link\" href=\"#sec-archstudio\"><span class=\"num\">22</span>Architecture Design Studio</a>\n      <a class=\"nav-link\" href=\"#sec-opscenter\"><span class=\"num\">23</span>Operations Center</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 7 \u00b7 Dashboards</div>\n      <a class=\"nav-link\" href=\"#sec-console10\"><span class=\"num\">24</span>Console Simulator</a>\n      <a class=\"nav-link\" href=\"#sec-execdash\"><span class=\"num\">25</span>Executive Dashboard</a>\n      <a class=\"nav-link\" href=\"#sec-opshealthdash\"><span class=\"num\">26</span>Operations Health Dashboard</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 8 \u00b7 Capstone Lab</div>\n      <a class=\"nav-link\" href=\"#sec-enterpriselab\"><span class=\"num\">27</span>Comprehensive Enterprise Lab</a>\n      <a class=\"nav-link\" href=\"#sec-enterprisetrouble\"><span class=\"num\">28</span>Enterprise Troubleshooting</a>\n    </div>\n    <div class=\"nav-group\"><div class=\"nav-head\">Module 9 \u00b7 Certification Center</div>\n      <a class=\"nav-link\" href=\"#sec-cheatsheet10\"><span class=\"num\">29</span>Final Revision Cheat Sheets</a>\n      <a class=\"nav-link\" href=\"#sec-flashcards10\"><span class=\"num\">30</span>Flash Cards</a>\n      <a class=\"nav-link\" href=\"#sec-mockexam\"><span class=\"num\">31</span>Mock Exam</a>\n      <a class=\"nav-link\" href=\"#sec-cert10\"><span class=\"num\">32</span>Score Report &amp; Certificate</a>\n    </div>\n  </nav>\n  <main>\n    <section id=\"hero\">\n      <span class=\"eyebrow\">\u25cf Oracle Cloud Infrastructure \u2014 Enterprise Operations Capstone</span>\n      <h1>Day 10: Govern it,<br>optimize it, <span class=\"accent\">own it.</span></h1>\n      <p class=\"lede\">The capstone \u2014 enterprise governance, organization management, cost optimization, security posture, compliance readiness, and a full end-to-end banking platform case study, all in one operations command center.</p>\n      <div class=\"hero-stats\">\n        <div class=\"hstat\"><b>32</b><span>Interactive sections</span></div>\n        <div class=\"hstat\"><b id=\"hero-quiz-count\">20</b><span>Mock exam questions</span></div>\n        <div class=\"hstat\"><b>14</b><span>Live simulators</span></div>\n        <div class=\"hstat\"><b id=\"hero-progress\">0%</b><span>Your progress</span></div>\n      </div>\n      <div class=\"cta-row\">\n        <a href=\"#sec-governance-review\" class=\"btn btn-primary\">Start the capstone \u2192</a>\n        <a href=\"#sec-mockexam\" class=\"btn btn-ghost\">Jump to mock exam</a>\n      </div>\n    </section>\n    <div class=\"container\">\n<!-- 01 GOVERNANCE REVIEW -->\n<section class=\"chapter reveal\" id=\"sec-governance-review\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">01</span><span class=\"track\">Enterprise Governance</span></div>\n  <h2>Enterprise Governance Review</h2>\n  <p class=\"dek\">Every governance control from this course works together as one system. Click each piece to recall how it fits.</p>\n  <div class=\"grid grid-4\" id=\"gov-review-grid\">\n    <div class=\"card\" data-gr=\"compartments\"><h4>Compartments</h4><p>Logical isolation boundary for resources.</p></div>\n    <div class=\"card\" data-gr=\"policies\"><h4>Policies</h4><p>Declarative authorization rules per compartment.</p></div>\n    <div class=\"card\" data-gr=\"groups\"><h4>Groups &amp; RBAC</h4><p>Permissions attached to roles, not individuals.</p></div>\n    <div class=\"card\" data-gr=\"identitydomains\"><h4>Identity Domains</h4><p>Isolated identity populations within a tenancy.</p></div>\n    <div class=\"card\" data-gr=\"tagging\"><h4>Tagging</h4><p>Defined + freeform tags for cost and governance tracking.</p></div>\n    <div class=\"card\" data-gr=\"quotas\"><h4>Quotas &amp; Budgets</h4><p>Self-imposed caps on consumption and spend.</p></div>\n    <div class=\"card\" data-gr=\"cloudguard\"><h4>Cloud Guard &amp; Security Zones</h4><p>Detect+respond, and hard-block, respectively.</p></div>\n    <div class=\"card\" data-gr=\"orgmgmt\"><h4>Organization Management</h4><p>Links multiple tenancies for centralized billing.</p></div>\n  </div>\n  <div class=\"pki-detail mt-lg\" id=\"gov-review-detail\">Click any control above to see how it connects to the others.</div>\n</section>\n\n<!-- 02 ENTERPRISE TENANCY DESIGNER -->\n<section class=\"chapter reveal\" id=\"sec-tenancydesigner\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">02</span><span class=\"track\">Enterprise Governance</span></div>\n  <h2>Enterprise Tenancy Designer</h2>\n  <p class=\"dek\">Build a compartment structure for a real enterprise. The validator checks naming, governance, security, and scalability.</p>\n  <div class=\"panel\">\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap; margin-bottom:14px;\">\n      <input class=\"mini-input\" id=\"td-name\" placeholder=\"compartment name\" style=\"flex:1;\">\n      <select class=\"mini-input\" id=\"td-parent\"><option value=\"root\">root</option></select>\n      <button class=\"chip-btn active\" id=\"td-add\">\uff0b Add compartment</button>\n    </div>\n    <div class=\"td-canvas\">\n      <div class=\"td-tree\" id=\"td-tree\"></div>\n    </div>\n    <div class=\"vcnb-validation\" id=\"td-validation\"></div>\n  </div>\n</section>\n\n<!-- 03 GOVERNANCE CHECKLIST -->\n<section class=\"chapter reveal\" id=\"sec-governancechecklist\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">03</span><span class=\"track\">Enterprise Governance</span></div>\n  <h2>Governance Checklist</h2>\n  <p class=\"dek\">Check off each control as your organization implements it \u2014 the score updates live.</p>\n  <div class=\"panel\">\n    <div class=\"score-ring-sm\" id=\"gc-ring\" style=\"--s:0; margin-bottom:16px;\"><span id=\"gc-score-val\">0%</span></div>\n    <div id=\"gc-list\"></div>\n  </div>\n</section>\n\n<!-- 04 POLICY DESIGNER -->\n<section class=\"chapter reveal\" id=\"sec-policydesigner\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">04</span><span class=\"track\">Enterprise Governance</span></div>\n  <h2>IAM Policy Designer</h2>\n  <p class=\"dek\">Pick a scenario, or write your own \u2014 the builder validates syntax and suggests improvements.</p>\n  <div class=\"panel\">\n    <div class=\"policy-scenarios\" id=\"policy-scenario-btns\">\n      <button class=\"chip-btn active\" data-pscenario=\"devteam\">Dev team, full control in Dev only</button>\n      <button class=\"chip-btn\" data-pscenario=\"auditor\">Read-only auditor, entire tenancy</button>\n      <button class=\"chip-btn\" data-pscenario=\"dba\">DBA, database-family only</button>\n    </div>\n    <div class=\"policy-editor mt-lg\"><textarea id=\"pd-editor\" spellcheck=\"false\"></textarea></div>\n    <button class=\"chip-btn active mt-lg\" id=\"pd-validate\">Validate syntax</button>\n    <div class=\"policy-verdict\" id=\"pd-verdict\"></div>\n  </div>\n</section>\n\n<!-- 05 TAGGING STRATEGY -->\n<section class=\"chapter reveal\" id=\"sec-taggingstrategy\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">05</span><span class=\"track\">Enterprise Governance</span></div>\n  <h2>Tagging Strategy</h2>\n  <p class=\"dek\">Build a defined tag namespace covering the standard enterprise dimensions.</p>\n  <div class=\"panel\">\n    <div id=\"tag-namespace-rows\"></div>\n    <button class=\"chip-btn active mt-lg\" id=\"tag-validate\">Validate tagging strategy</button>\n    <p class=\"small mt-lg\" id=\"tag-validate-result\"></p>\n  </div>\n</section>\n<!-- 06 ORGANIZATION MANAGEMENT -->\n<section class=\"chapter reveal\" id=\"sec-orgmgmt\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">06</span><span class=\"track\">Organization Mgmt</span></div>\n  <h2>Organization Management</h2>\n  <p class=\"dek\">A parent organization links multiple tenancies \u2014 separate IAM, consolidated billing and governance oversight.</p>\n  <div class=\"grid grid-4\">\n    <div class=\"card\"><h4>Parent Tenancy</h4><p>The billing and governance root of the organization.</p></div>\n    <div class=\"card\"><h4>Child Tenancies</h4><p>Fully IAM-isolated tenancies linked to the parent.</p></div>\n    <div class=\"card\"><h4>Business Units</h4><p>Each child often maps to a division, subsidiary, or acquisition.</p></div>\n    <div class=\"card\"><h4>Resource Sharing</h4><p>Selected resources (e.g. via RPC) can be shared across linked tenancies without merging IAM.</p></div>\n  </div>\n</section>\n\n<!-- 07 MULTI-TENANCY DESIGNER -->\n<section class=\"chapter reveal\" id=\"sec-multitenancy\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">07</span><span class=\"track\">Organization Mgmt</span></div>\n  <h2>Multi-Tenancy Designer</h2>\n  <p class=\"dek\">Link business-unit tenancies to a parent and get architecture feedback.</p>\n  <div class=\"panel\">\n    <div class=\"org-canvas\">\n      <div class=\"org-parent-box\">\ud83c\udfdb Parent Organization (Billing Root)</div>\n      <div class=\"org-children-row\" id=\"org-children-row\"></div>\n    </div>\n    <div style=\"display:flex; gap:8px; margin-top:16px;\">\n      <input class=\"mini-input\" id=\"org-child-name\" placeholder=\"business unit name, e.g. Finance\" style=\"flex:1;\">\n      <button class=\"chip-btn active\" id=\"org-child-add\">\uff0b Link tenancy</button>\n    </div>\n  </div>\n</section>\n\n<!-- 08 LANDING ZONE DESIGN -->\n<section class=\"chapter reveal\" id=\"sec-landingzone\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">08</span><span class=\"track\">Organization Mgmt</span></div>\n  <h2>Landing Zone Design</h2>\n  <p class=\"dek\">A Landing Zone is the pre-built, compliant baseline every new workload deploys into. Configure each layer.</p>\n  <div class=\"panel\" id=\"lz-layers\"></div>\n</section>\n<!-- 09 COST ANALYSIS DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-costanalysis\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">09</span><span class=\"track\">Cost Optimization</span></div>\n  <h2>Cost Analysis Dashboard</h2>\n  <p class=\"dek\">An executive-level view of spend across the enterprise.</p>\n  <div class=\"bill-stats\">\n    <div class=\"bill-stat\"><div class=\"label\">Month to Date</div><div class=\"val\">$182,400</div><div class=\"delta up\">\u25b2 8% vs last month</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">Forecast (EOM)</div><div class=\"val\">$268,000</div><div class=\"delta up\">\u25b2 trending over budget</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">Largest Department</div><div class=\"val\">Engineering</div><div class=\"delta\">42% of spend</div></div>\n    <div class=\"bill-stat\"><div class=\"label\">YoY Trend</div><div class=\"val\">+14%</div><div class=\"delta up\">\u25b2 growth</div></div>\n  </div>\n  <div class=\"grid grid-2 mt-lg\">\n    <div class=\"panel\"><h4 style=\"margin-bottom:10px;\">Cost by Department</h4><canvas id=\"deptPieChart\" width=\"260\" height=\"200\"></canvas><div class=\"pie-legend\" id=\"dept-pie-legend\"></div></div>\n    <div class=\"panel\"><h4 style=\"margin-bottom:10px;\">6-Month Trend</h4><canvas id=\"trend10Chart\" width=\"400\" height=\"200\"></canvas></div>\n  </div>\n</section>\n\n<!-- 10 RIGHT SIZING -->\n<section class=\"chapter reveal\" id=\"sec-rightsizing\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">10</span><span class=\"track\">Cost Optimization</span></div>\n  <h2>Right Sizing</h2>\n  <div class=\"panel\">\n    <div class=\"rs-shape selected\" data-rs10=\"over\"><span><strong>analytics-vm-03</strong> \u2014 16 OCPU \u2014 avg CPU 7%</span><span class=\"small\">Currently running</span></div>\n    <div class=\"rs-shape\" data-rs10=\"auto\"><span><strong>api-vm-cluster</strong> \u2014 fixed 6 instances \u2014 traffic varies 3x daily</span><span class=\"small\">Currently running</span></div>\n    <div class=\"rs-savings\" id=\"rs10-savings\"></div>\n  </div>\n</section>\n\n<!-- 11 IDLE RESOURCE DETECTOR -->\n<section class=\"chapter reveal\" id=\"sec-idledetector\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">11</span><span class=\"track\">Cost Optimization</span></div>\n  <h2>Idle Resource Detector</h2>\n  <p class=\"dek\">Clean up detected idle resources and watch monthly cost drop in real time.</p>\n  <div class=\"panel\">\n    <div class=\"center\" style=\"margin-bottom:16px;\"><span class=\"small\">Monthly waste detected:</span><br><span class=\"savings-counter\" id=\"idle-total\">$4,260</span></div>\n    <div id=\"idle-list\"></div>\n  </div>\n</section>\n\n<!-- 12 COMMITMENT DISCOUNTS -->\n<section class=\"chapter reveal\" id=\"sec-commitmentdiscounts\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">12</span><span class=\"track\">Cost Optimization</span></div>\n  <h2>Commitment Discounts</h2>\n  <p class=\"dek\">Trading flexibility for lower unit cost, at scale.</p>\n  <table class=\"cmp\">\n    <tr><th>Model</th><th>Commitment</th><th>Typical Discount</th><th>Best for</th></tr>\n    <tr><td>Pay As You Go</td><td>None</td><td>0%</td><td>Unpredictable, early-stage workloads</td></tr>\n    <tr><td>Capacity Reservation</td><td>Reserve specific shape/AD capacity</td><td>0% (guarantees availability, not price)</td><td>Guaranteed capacity for critical launches</td></tr>\n    <tr><td>Annual/Multi-Year Commitment</td><td>1-3 year spend commitment</td><td>~20-40%</td><td>Stable, predictable baseline usage</td></tr>\n  </table>\n  <div class=\"panel mt-lg\">\n    <div class=\"field-row\"><label>Predictable baseline spend (% of total)</label><input type=\"range\" id=\"commit-slider\" min=\"0\" max=\"100\" value=\"60\" style=\"width:100%; accent-color:var(--red);\"><p class=\"small\">Baseline: <strong id=\"commit-val\">60%</strong></p></div>\n    <p class=\"small mt-lg\" id=\"commit-reco\"></p>\n  </div>\n</section>\n\n<!-- 13 FINOPS DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-finopsdash\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">13</span><span class=\"track\">Cost Optimization</span></div>\n  <h2>FinOps Dashboard</h2>\n  <div class=\"exec-grid\">\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:74; --ring-color:var(--green);\"><span>74</span></div><div class=\"k-label\">Optimization Score</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:89; --ring-color:var(--blue);\"><span>89%</span></div><div class=\"k-label\">Budget Utilized</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:38; --ring-color:var(--amber);\"><span>$4.2k</span></div><div class=\"k-label\">Savings Available</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:60; --ring-color:var(--red-bright);\"><span>6</span></div><div class=\"k-label\">Open Recommendations</div></div>\n  </div>\n</section>\n<!-- 14 SECURITY POSTURE REVIEW -->\n<section class=\"chapter reveal\" id=\"sec-securityposture\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">14</span><span class=\"track\">Security Posture</span></div>\n  <h2>Security Posture Review</h2>\n  <p class=\"dek\">A composite score across every security control covered in this course.</p>\n  <div class=\"exec-grid\">\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:82; --ring-color:var(--green);\"><span>82</span></div><div class=\"k-label\">IAM &amp; Identity</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:70; --ring-color:var(--amber);\"><span>70</span></div><div class=\"k-label\">Vault &amp; Encryption</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:55; --ring-color:var(--red-bright);\"><span>55</span></div><div class=\"k-label\">Cloud Guard Coverage</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:91; --ring-color:var(--green);\"><span>91</span></div><div class=\"k-label\">Logging &amp; Audit</div></div>\n  </div>\n</section>\n\n<!-- 15 SECURITY GAP ANALYZER -->\n<section class=\"chapter reveal\" id=\"sec-securitygap\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">15</span><span class=\"track\">Security Posture</span></div>\n  <h2>Security Gap Analyzer</h2>\n  <p class=\"dek\">Detected findings across the environment.</p>\n  <div class=\"panel\" id=\"secgap-panel\"></div>\n</section>\n\n<!-- 16 REMEDIATION PLANNER -->\n<section class=\"chapter reveal\" id=\"sec-remediation\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">16</span><span class=\"track\">Security Posture</span></div>\n  <h2>Remediation Planner</h2>\n  <p class=\"dek\">Fix findings from the Gap Analyzer \u2014 the security score climbs as you go.</p>\n  <div class=\"panel\">\n    <div class=\"score-ring-sm\" id=\"remediation-ring\" style=\"--s:55; margin-bottom:16px;\"><span id=\"remediation-score-val\">55</span></div>\n    <div id=\"remediation-list\"></div>\n  </div>\n</section>\n\n<!-- 17 PATCH MANAGEMENT & BACKUP VALIDATION -->\n<section class=\"chapter reveal\" id=\"sec-patchbackup\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">17</span><span class=\"track\">Security Posture</span></div>\n  <h2>Patch Management &amp; Backup Validation</h2>\n  <h3>Maintenance planner</h3>\n  <div class=\"panel\">\n    <table class=\"console-table\"><thead><tr><th>Fleet</th><th>Patch Status</th><th>Next Window</th></tr></thead>\n      <tbody>\n        <tr><td>Web tier (12 instances)</td><td><span class=\"status-pill active\">Up to date</span></td><td>\u2014</td></tr>\n        <tr><td>DB tier (4 instances)</td><td><span class=\"status-pill deleted\">3 pending</span></td><td id=\"patch-window\">Not scheduled</td></tr>\n      </tbody></table>\n    <button class=\"chip-btn active mt-lg\" id=\"patch-schedule\">Schedule maintenance window</button>\n  </div>\n  <h3>Backup restore validation</h3>\n  <div class=\"panel mt-lg\">\n    <button class=\"chip-btn active\" id=\"backup-restore-test\">\ud83d\udd04 Run test restore</button>\n    <div class=\"lw-boot-log\" id=\"backup-restore-log\"></div>\n  </div>\n</section>\n\n<!-- 18 COMPLIANCE MATRIX -->\n<section class=\"chapter reveal\" id=\"sec-compliancematrix\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">18</span><span class=\"track\">Compliance</span></div>\n  <h2>Compliance Matrix</h2>\n  <p class=\"dek\">Click a framework for what it primarily governs and which OCI controls map to it.</p>\n  <div class=\"compliance-grid\" id=\"compliance10-grid\">\n    <div class=\"compliance-card\" data-c10=\"iso\">ISO 27001</div>\n    <div class=\"compliance-card\" data-c10=\"soc2\">SOC 2</div>\n    <div class=\"compliance-card\" data-c10=\"pci\">PCI DSS</div>\n    <div class=\"compliance-card\" data-c10=\"hipaa\">HIPAA</div>\n    <div class=\"compliance-card\" data-c10=\"gdpr\">GDPR</div>\n    <div class=\"compliance-card\" data-c10=\"nist\">NIST</div>\n    <div class=\"compliance-card\" data-c10=\"cis\">CIS Benchmarks</div>\n  </div>\n  <div class=\"cia-detail mt-lg\" id=\"compliance10-detail\">Click a framework above.</div>\n</section>\n\n<!-- 19 AUDIT READINESS -->\n<section class=\"chapter reveal\" id=\"sec-auditreadiness\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">19</span><span class=\"track\">Compliance</span></div>\n  <h2>Audit Readiness Checklist</h2>\n  <div class=\"panel\" id=\"audit-readiness-list\"></div>\n</section>\n\n<!-- 20 COMPLIANCE REPORT -->\n<section class=\"chapter reveal\" id=\"sec-compliancereport\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">20</span><span class=\"track\">Compliance</span></div>\n  <h2>Compliance Report</h2>\n  <p class=\"dek\">Generate an executive-ready compliance summary from your Audit Readiness answers above.</p>\n  <div class=\"panel\">\n    <button class=\"chip-btn active\" id=\"compliance-report-generate\">Generate Report</button>\n    <div class=\"lw-boot-log\" id=\"compliance-report-out\" style=\"display:none;\"></div>\n  </div>\n</section>\n<!-- 21 BANKING PLATFORM CASE STUDY -->\n<section class=\"chapter reveal\" id=\"sec-casestudy\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">21</span><span class=\"track\">Case Study</span></div>\n  <h2>End-to-End Operations Case Study: Enterprise Banking Platform</h2>\n  <p class=\"dek\">Every service from this course, integrated into one architecture. Click each component.</p>\n  <div class=\"studio-layer-grid\" id=\"casestudy-grid\">\n    <div class=\"studio-component\" data-cs=\"iam\">IAM &amp; Policies</div>\n    <div class=\"studio-component\" data-cs=\"terraform\">Terraform</div>\n    <div class=\"studio-component\" data-cs=\"vcn\">VCN &amp; Subnets</div>\n    <div class=\"studio-component\" data-cs=\"compute\">Compute</div>\n    <div class=\"studio-component\" data-cs=\"block\">Block Storage</div>\n    <div class=\"studio-component\" data-cs=\"object\">Object Storage</div>\n    <div class=\"studio-component\" data-cs=\"vault\">Vault</div>\n    <div class=\"studio-component\" data-cs=\"lb\">Load Balancer</div>\n    <div class=\"studio-component\" data-cs=\"monitoring\">Monitoring</div>\n    <div class=\"studio-component\" data-cs=\"logging\">Logging</div>\n    <div class=\"studio-component\" data-cs=\"cloudguard\">Cloud Guard</div>\n    <div class=\"studio-component\" data-cs=\"backup\">Backup &amp; DR</div>\n  </div>\n  <div class=\"pki-detail mt-lg\" id=\"casestudy-detail\">Click a component to see its role in the banking platform.</div>\n</section>\n\n<!-- 22 ARCHITECTURE DESIGN STUDIO -->\n<section class=\"chapter reveal\" id=\"sec-archstudio\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">22</span><span class=\"track\">Case Study</span></div>\n  <h2>Architecture Design Studio</h2>\n  <p class=\"dek\">Assemble a complete architecture. Add components, then score your design.</p>\n  <div class=\"panel\">\n    <div class=\"studio-layer-grid\" id=\"studio-components\">\n      <div class=\"studio-component\" data-comp=\"compartments\">Compartments</div>\n      <div class=\"studio-component\" data-comp=\"iam\">IAM Policies</div>\n      <div class=\"studio-component\" data-comp=\"vcn\">VCN + Subnets</div>\n      <div class=\"studio-component\" data-comp=\"secgroups\">Security Lists/NSGs</div>\n      <div class=\"studio-component\" data-comp=\"compute\">Compute + Autoscale</div>\n      <div class=\"studio-component\" data-comp=\"lb\">Load Balancer</div>\n      <div class=\"studio-component\" data-comp=\"storage\">Block/Object Storage</div>\n      <div class=\"studio-component\" data-comp=\"vault\">Vault + Encryption</div>\n      <div class=\"studio-component\" data-comp=\"monitoring\">Monitoring + Alarms</div>\n      <div class=\"studio-component\" data-comp=\"logging\">Logging</div>\n      <div class=\"studio-component\" data-comp=\"cloudguard\">Cloud Guard</div>\n      <div class=\"studio-component\" data-comp=\"dr\">Backup + DR</div>\n    </div>\n    <button class=\"chip-btn active mt-lg\" id=\"studio-score\">Score my architecture</button>\n    <div class=\"design-grid mt-lg\">\n      <div class=\"panel center\"><div class=\"design-score-ring\" id=\"studio-ring\" style=\"--dscore:0; margin:0 auto;\"><span id=\"studio-score-val\">0</span></div></div>\n      <div class=\"panel\"><p class=\"small\" id=\"studio-feedback\">Add components, then score your design.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- 23 OPERATIONS CENTER -->\n<section class=\"chapter reveal\" id=\"sec-opscenter\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">23</span><span class=\"track\">Case Study</span></div>\n  <h2>Operations Center</h2>\n  <p class=\"dek\">A single integrated dashboard covering the full operations lifecycle for the banking platform.</p>\n  <div class=\"panel\">\n    <div class=\"opscenter-tabs\" id=\"opscenter-tabs\">\n      <button class=\"chip-btn active\" data-ops=\"deploy\">Deployment</button>\n      <button class=\"chip-btn\" data-ops=\"monitor\">Monitoring</button>\n      <button class=\"chip-btn\" data-ops=\"incident\">Incident Response</button>\n      <button class=\"chip-btn\" data-ops=\"scale\">Scaling</button>\n      <button class=\"chip-btn\" data-ops=\"cost\">Cost Review</button>\n      <button class=\"chip-btn\" data-ops=\"security\">Security Review</button>\n      <button class=\"chip-btn\" data-ops=\"backup\">Backup</button>\n      <button class=\"chip-btn\" data-ops=\"dr\">DR Test</button>\n      <button class=\"chip-btn\" data-ops=\"audit\">Compliance Audit</button>\n    </div>\n    <div class=\"incident-findings\" id=\"opscenter-panel\"></div>\n  </div>\n</section>\n<!-- 24 CONSOLE SIMULATOR -->\n<section class=\"chapter reveal\" id=\"sec-console10\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">24</span><span class=\"track\">Dashboards</span></div>\n  <h2>OCI Console Simulator</h2>\n  <div class=\"console-sim\">\n    <div class=\"console-tb\"><div class=\"dots\"><span style=\"background:#ff5f57\"></span><span style=\"background:#febc2e\"></span><span style=\"background:#28c840\"></span></div><span class=\"small mono\">console.oracle-simulator.local/enterprise</span></div>\n    <div class=\"console-body\">\n      <div class=\"console-nav\">\n        <div class=\"active\" data-panel10=\"identity10\">\ud83d\udc64 Identity</div>\n        <div data-panel10=\"terraform10\">\ud83e\uddf1 Resource Manager</div>\n        <div data-panel10=\"vault10\">\ud83d\udd10 Vault</div>\n        <div data-panel10=\"monitoring10\">\ud83d\udcca Monitoring</div>\n        <div data-panel10=\"cloudguard10\">\ud83d\udee1 Cloud Guard</div>\n      </div>\n      <div class=\"console-main\">\n        <div class=\"console-panel10\" id=\"panel10-identity10\">\n          <table class=\"console-table\"><thead><tr><th>Compartment</th><th>Resources</th></tr></thead>\n          <tbody><tr><td>Production</td><td>142</td></tr><tr><td>Security</td><td>18</td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel10\" id=\"panel10-terraform10\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Stack</th><th>State</th></tr></thead>\n          <tbody><tr><td>banking-platform-vcn</td><td><span class=\"status-pill active\">Applied</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel10\" id=\"panel10-vault10\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Vault</th><th>Keys</th></tr></thead>\n          <tbody><tr><td>prod-vault</td><td>6</td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel10\" id=\"panel10-monitoring10\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Alarm</th><th>Status</th></tr></thead>\n          <tbody><tr><td>High CPU \u2014 db-tier</td><td><span class=\"status-pill deleted\">Firing</span></td></tr></tbody></table>\n        </div>\n        <div class=\"console-panel10\" id=\"panel10-cloudguard10\" style=\"display:none;\">\n          <table class=\"console-table\"><thead><tr><th>Problem</th><th>Risk</th></tr></thead>\n          <tbody><tr><td>Root API key in use</td><td><span class=\"priority-pill priority-med\">Medium</span></td></tr></tbody></table>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 25 EXECUTIVE DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-execdash\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">25</span><span class=\"track\">Dashboards</span></div>\n  <h2>Executive Dashboard</h2>\n  <p class=\"dek\">Your overall cloud maturity score, computed from every module above.</p>\n  <div class=\"exec-overall\">\n    <div class=\"score-ring-sm\" id=\"exec-overall-ring\" style=\"width:140px; height:140px; --s:0;\"><span id=\"exec-overall-val\" style=\"font-size:28px;\">0</span></div>\n    <p class=\"mt-lg\" style=\"color:var(--text-2);\">Overall Cloud Maturity Score</p>\n  </div>\n  <div class=\"exec-grid mt-lg\">\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:78;\"><span>78</span></div><div class=\"k-label\">Governance</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:69; --ring-color:var(--amber);\"><span>69</span></div><div class=\"k-label\">Security</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:74;\"><span>74</span></div><div class=\"k-label\">Cost</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:85;\"><span>85</span></div><div class=\"k-label\">Compliance</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:91;\"><span>91</span></div><div class=\"k-label\">Availability</div></div>\n    <div class=\"score-kpi\"><div class=\"score-ring-sm\" style=\"--s:80;\"><span>80</span></div><div class=\"k-label\">Operations</div></div>\n  </div>\n</section>\n\n<!-- 26 OPERATIONS HEALTH DASHBOARD -->\n<section class=\"chapter reveal\" id=\"sec-opshealthdash\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">26</span><span class=\"track\">Dashboards</span></div>\n  <h2>Operations Health Dashboard</h2>\n  <div class=\"livemon-grid\" id=\"opshealth-grid\"></div>\n</section>\n<!-- 27 COMPREHENSIVE ENTERPRISE LAB -->\n<section class=\"chapter reveal\" id=\"sec-enterpriselab\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">27</span><span class=\"track\">Capstone Lab</span></div>\n  <h2>Comprehensive Enterprise Lab</h2>\n  <p class=\"dek\">Build a complete enterprise OCI environment end to end. Check off each piece.</p>\n  <div class=\"enterprise-lab-grid\" id=\"enterprise-lab-grid\"></div>\n  <p class=\"small center mt-lg\" id=\"enterprise-lab-progress\">0 / 16 complete</p>\n</section>\n\n<!-- 28 ENTERPRISE TROUBLESHOOTING -->\n<section class=\"chapter reveal\" id=\"sec-enterprisetrouble\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">28</span><span class=\"track\">Capstone Lab</span></div>\n  <h2>Enterprise Troubleshooting</h2>\n  <p class=\"dek\">Draw on everything from the whole course to resolve each incident.</p>\n  <div class=\"cost-filters\" id=\"ent-trouble-btns\">\n    <button class=\"chip-btn active\" data-etcase=\"security\">Security Incident</button>\n    <button class=\"chip-btn\" data-etcase=\"budget\">Budget Overrun</button>\n    <button class=\"chip-btn\" data-etcase=\"network\">Network Failure</button>\n    <button class=\"chip-btn\" data-etcase=\"terraform\">Terraform Failure</button>\n    <button class=\"chip-btn\" data-etcase=\"vault\">Vault Access Error</button>\n    <button class=\"chip-btn\" data-etcase=\"monitoring\">Monitoring Failure</button>\n    <button class=\"chip-btn\" data-etcase=\"lb\">Load Balancer Failure</button>\n    <button class=\"chip-btn\" data-etcase=\"dr\">DR Failure</button>\n  </div>\n  <div class=\"panel\" id=\"ent-trouble-panel\"></div>\n</section>\n\n<!-- 29 CHEAT SHEETS -->\n<section class=\"chapter reveal\" id=\"sec-cheatsheet10\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">29</span><span class=\"track\">Certification Center</span></div>\n  <h2>Final Revision Cheat Sheets</h2>\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><h4>Governance</h4><ul style=\"margin-left:16px;\"><li>Compartments isolate; Policies authorize; Tags classify</li><li>Quotas = self-imposed; Limits = provider ceiling</li><li>Org Management links billing, not IAM</li></ul></div>\n    <div class=\"card\"><h4>Cost</h4><ul style=\"margin-left:16px;\"><li>Right-size on actual utilization, not guesses</li><li>Idle resources are the fastest, safest savings</li><li>Commitments trade flexibility for discount at scale</li></ul></div>\n    <div class=\"card\"><h4>Security &amp; Compliance</h4><ul style=\"margin-left:16px;\"><li>Security posture = IAM + Vault + Cloud Guard + Logging combined</li><li>Security Zones block; Cloud Guard detects+responds</li><li>Map each framework to concrete technical controls, not just a checkbox</li></ul></div>\n    <div class=\"card\"><h4>Operations</h4><ul style=\"margin-left:16px;\"><li>Terraform provisions; Ansible configures</li><li>Always validate DR with an actual failover test</li><li>Executive dashboards roll up governance+security+cost+compliance+availability+ops</li></ul></div>\n  </div>\n</section>\n\n<!-- 30 FLASHCARDS -->\n<section class=\"chapter reveal\" id=\"sec-flashcards10\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">30</span><span class=\"track\">Certification Center</span></div>\n  <h2>Flash Cards</h2>\n  <div class=\"flash-wrap\" id=\"flash-wrap10\"></div>\n</section>\n\n<!-- 31 MOCK EXAM -->\n<section class=\"chapter reveal\" id=\"sec-mockexam\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">31</span><span class=\"track\">Certification Center</span></div>\n  <h2>Mock Exam</h2>\n  <p class=\"dek\">20 questions spanning every domain from the course. Domain-wise performance is tracked below as you answer.</p>\n  <div class=\"panel\" id=\"domain-performance\"></div>\n  <div id=\"quiz-wrap10\" class=\"mt-lg\"></div>\n  <div class=\"panel center mt-lg\"><p>Your score: <b id=\"quiz-final-score10\" style=\"color:var(--red-bright); font-family:var(--font-display); font-size:20px;\">0 / 20</b></p></div>\n</section>\n\n<!-- 32 SCORE REPORT & CERTIFICATE -->\n<section class=\"chapter reveal\" id=\"sec-cert10\">\n  <div class=\"chapter-kicker\"><span class=\"idx\">32</span><span class=\"track\">Certification Center</span></div>\n  <h2>Score Report &amp; Certificate Preview</h2>\n  <div class=\"center\" style=\"padding:20px 0 40px;\">\n    <div class=\"badge-circle\" id=\"badge-circle10\"><span id=\"badge-pct10\">0%</span></div>\n    <h3 id=\"badge-title10\">Keep going</h3>\n    <p class=\"small\" id=\"badge-sub10\">Complete every section and the mock exam to preview your capstone certificate.</p>\n  </div>\n  <div class=\"cert-frame\">\n    <p class=\"small\">ORACLE CLOUD INFRASTRUCTURE</p>\n    <h3>Certificate of Completion</h3>\n    <p class=\"small\">This certifies that</p>\n    <div class=\"cert-name\">Your Name</div>\n    <p class=\"small\">has completed <strong>Day 10: Enterprise Governance, Cost, Security &amp; Operations Capstone</strong></p>\n    <p class=\"small mt-lg\">Score: <span id=\"cert-score-display10\">0/20</span> \u00b7 Date: <span id=\"cert-date-display10\"></span></p>\n  </div>\n</section>\n\n</div>\n</main>\n</div>\n<footer>OCI Enterprise Governance, Cost, Security &amp; Operations \u2014 Day 10 Capstone \u00b7 Interactive Learning Platform \u00b7 Single self-contained HTML file \u00b7 No external dependencies</footer>\n\n\n\n\n\n\n\n\n\n", "js": "\nconst state = { quizScore:0, quizAnswered:0, quizTotal:0, labsDone:new Set() };\ndocument.addEventListener('DOMContentLoaded', () => {\n  initParticles(); initProgressBar(); initSidebar(); initSearch(); initTheme(); initReveal();\n  initGovReview(); initTenancyDesigner(); initGovChecklist(); initPolicyDesigner(); initTaggingStrategy();\n  initOrgMgmt(); initLandingZone();\n  initCostAnalysis10(); initRightSizing10(); initIdleDetector(); initCommitment(); \n  initSecurityGap(); initRemediation(); initPatchBackup();\n  initCompliance10(); initAuditReadiness(); initComplianceReport();\n  initCaseStudy(); initArchStudio(); initOpsCenter();\n  initConsoleSim10(); initOpsHealth();\n  initEnterpriseLab(); initEnterpriseTrouble();\n  initFlashcards10(); initQuiz10(); updateBadge10();\n});\nfunction initParticles(){\n  const c=document.getElementById('particles'); const ctx=c.getContext('2d'); let w,h,particles=[];\n  function resize(){ w=c.width=window.innerWidth; h=c.height=window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  const N=Math.min(60, Math.floor(window.innerWidth/24));\n  for(let i=0;i<N;i++) particles.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.6+0.4,vx:(Math.random()-0.5)*0.15,vy:(Math.random()-0.5)*0.15});\n  function tick(){ ctx.clearRect(0,0,w,h); ctx.fillStyle='rgba(199,70,52,0.5)';\n    particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; if(p.x<0)p.x=w; if(p.x>w)p.x=0; if(p.y<0)p.y=h; if(p.y>h)p.y=0; ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill(); });\n    requestAnimationFrame(tick);\n  }\n  tick();\n}\nfunction initProgressBar(){\n  const bar=document.getElementById('progress-bar'); const heroProgress=document.getElementById('hero-progress');\n  window.addEventListener('scroll', ()=>{\n    const scrollTop=window.scrollY; const docH=document.documentElement.scrollHeight-window.innerHeight;\n    const pct=docH>0?(scrollTop/docH)*100:0;\n    bar.style.width=pct+'%'; if(heroProgress) heroProgress.textContent=Math.round(pct)+'%';\n    window.__lastScrollPct10=pct; updateBadge10(); highlightActiveNav();\n  }, {passive:true});\n}\nfunction highlightActiveNav(){\n  const sections=document.querySelectorAll('section.chapter'); let current=null;\n  sections.forEach(sec=>{ const rect=sec.getBoundingClientRect(); if(rect.top<160) current=sec.id; });\n  document.querySelectorAll('#sidebar a.nav-link').forEach(a=>a.classList.toggle('active', a.getAttribute('href')==='#'+current));\n}\nfunction initSidebar(){ const sb=document.getElementById('sidebar'); document.getElementById('sidebar-toggle').addEventListener('click', ()=>sb.classList.toggle('collapsed')); }\nfunction initSearch(){\n  const input=document.getElementById('search'); const results=document.getElementById('search-results'); const index=[];\n  document.querySelectorAll('section.chapter').forEach(sec=>{\n    const title=sec.querySelector('h2')?.textContent || sec.id;\n    sec.querySelectorAll('h3').forEach(h3=>index.push({label:h3.textContent, cat:title, href:'#'+sec.id}));\n    index.push({label:title, cat:'Section', href:'#'+sec.id});\n  });\n  input.addEventListener('input', ()=>{\n    const q=input.value.trim().toLowerCase(); if(!q){results.style.display='none'; return;}\n    const matches=index.filter(i=>i.label.toLowerCase().includes(q)).slice(0,8);\n    results.innerHTML=matches.map(m=>`<a href=\"${m.href}\"><span class=\"sr-cat\">${m.cat}</span>${m.label}</a>`).join('') || '<a style=\"cursor:default;\">No results</a>';\n    results.style.display='block';\n  });\n  document.addEventListener('click', e=>{ if(!document.getElementById('search-wrap').contains(e.target)) results.style.display='none'; });\n  results.addEventListener('click', ()=>setTimeout(()=>{results.style.display='none'; input.value='';},10));\n}\nfunction initTheme(){\n  const btn=document.getElementById('theme-toggle');\n  btn.addEventListener('click', ()=>{ const html=document.documentElement; const isDark=html.getAttribute('data-theme')!=='light'; html.setAttribute('data-theme', isDark?'light':'dark'); btn.textContent=isDark?'\u2600\ufe0f':'\ud83c\udf19'; });\n}\nfunction initReveal(){\n  const els=document.querySelectorAll('.reveal');\n  const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('in');}), {threshold:0.08});\n  els.forEach(el=>io.observe(el));\n}\n\n;\n\n/* ---------- governance review ---------- */\nfunction initGovReview(){\n  const cards = document.querySelectorAll('#gov-review-grid .card'); if(!cards.length) return;\n  const detail = document.getElementById('gov-review-detail');\n  const info = {\n    compartments: 'Compartments are the foundation everything else attaches to \u2014 Policies target them, Quotas cap them, Tags classify what\\'s inside them.',\n    policies: 'Policies grant Groups specific verbs on resources within a Compartment \u2014 the enforcement layer for RBAC and least privilege.',\n    groups: 'Groups (and RBAC generally) mean permissions are managed at the role level, not per-user \u2014 critical for onboarding/offboarding at scale.',\n    identitydomains: 'Identity Domains let you segment user populations (e.g. a partner or dev-sandbox population) without polluting your main identity store.',\n    tagging: 'Defined Tags feed directly into Cost Analysis dashboards and governance reporting \u2014 untagged resources are invisible to department-level cost accountability.',\n    quotas: 'Quotas and Budgets are both self-imposed guardrails \u2014 Quotas cap resource counts, Budgets cap spend, both independent of hard provider Limits.',\n    cloudguard: 'Cloud Guard detects and responds after the fact; Security Zones block non-compliant actions outright \u2014 layered, not redundant.',\n    orgmgmt: 'Organization Management ties multiple tenancies together for consolidated billing and oversight, while keeping each tenancy\\'s IAM fully separate.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=> detail.textContent = info[c.dataset.gr]));\n}\n\n/* ---------- enterprise tenancy designer ---------- */\nfunction initTenancyDesigner(){\n  const addBtn = document.getElementById('td-add'); if(!addBtn) return;\n  let comps = [];\n  const parentSelect = document.getElementById('td-parent');\n  const tree = document.getElementById('td-tree');\n  function renderTree(){\n    function buildUl(parent){\n      const children = comps.filter(c=>c.parent===parent);\n      if(!children.length) return '';\n      return '<ul>' + children.map(c=>`<li><div class=\"node\"><span class=\"ic\">\ud83d\udcc1</span> ${c.name}</div>${buildUl(c.name)}</li>`).join('') + '</ul>';\n    }\n    tree.innerHTML = `<div class=\"node root\"><span class=\"ic\">\ud83c\udfdb</span> root</div>` + buildUl('root');\n    parentSelect.innerHTML = '<option value=\"root\">root</option>' + comps.map(c=>`<option value=\"${c.name}\">${c.name}</option>`).join('');\n  }\n  function validate(){\n    const val = document.getElementById('td-validation');\n    const names = comps.map(c=>c.name.toLowerCase());\n    const expected = ['development','testing','production','security','networking','shared services','finance'];\n    const covered = expected.filter(e=> names.some(n=> n.includes(e.split(' ')[0])));\n    const badNames = comps.filter(c=> /[A-Z\\s]/.test(c.name) === false ? false : /[A-Z]/.test(c.name) || / /.test(c.name));\n    let notes = [];\n    notes.push(covered.length>=5 ? `\u2713 ${covered.length}/7 recommended top-level domains covered (Dev/Test/Prod/Security/Networking/Shared/Finance).` : `\u26a0 Only ${covered.length}/7 recommended domains covered so far \u2014 consider adding more.`);\n    if(badNames.length) notes.push(`\u26a0 Naming: \"${badNames[0].name}\" uses uppercase or spaces \u2014 enterprise convention is lowercase-hyphenated.`);\n    else notes.push('\u2713 Naming convention looks consistent.');\n    val.className = 'vcnb-validation ' + (covered.length>=5 && !badNames.length ? 'ok' : 'bad');\n    val.innerHTML = notes.join('<br>');\n  }\n  addBtn.addEventListener('click', ()=>{\n    const name = document.getElementById('td-name').value.trim(); if(!name) return;\n    comps.push({name, parent: parentSelect.value});\n    document.getElementById('td-name').value='';\n    renderTree(); validate();\n  });\n  renderTree(); validate();\n}\n\n/* ---------- governance checklist ---------- */\nfunction initGovChecklist(){\n  const wrap = document.getElementById('gc-list'); if(!wrap) return;\n  const items = [\n    'Compartment structure separates Dev/Test/Prod',\n    'Least-privilege IAM policies (no broad \"manage all-resources\")',\n    'MFA enforced for all administrative users',\n    'Defined tags applied for cost-center and environment',\n    'Budgets configured with alert thresholds',\n    'Cloud Guard enabled at the tenancy root',\n    'Security Zones applied to production compartments',\n    'Quotas set to prevent runaway resource sprawl',\n  ];\n  wrap.innerHTML = items.map((t,i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div class=\"lab-title\">${t}</div></div>`).join('');\n  function updateScore(){\n    const done = wrap.querySelectorAll('.lab-item.done').length;\n    const pct = Math.round((done/items.length)*100);\n    document.getElementById('gc-ring').style.setProperty('--s', pct*3.6/3.6);\n    document.getElementById('gc-ring').style.setProperty('--s', pct);\n    document.getElementById('gc-score-val').textContent = pct+'%';\n  }\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=>{ item.classList.toggle('done'); updateScore(); }));\n  updateScore();\n}\n\n/* ---------- policy designer ---------- */\nfunction initPolicyDesigner(){\n  const btns = document.querySelectorAll('#policy-scenario-btns .chip-btn'); if(!btns.length) return;\n  const editor = document.getElementById('pd-editor');\n  const templates = {\n    devteam: 'Allow group DevTeam to manage all-resources in compartment Development',\n    auditor: 'Allow group Auditors to inspect all-resources in tenancy',\n    dba: 'Allow group DBAs to manage database-family in compartment Production'\n  };\n  function render(key){ editor.value = templates[key]; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.pscenario); }));\n  render('devteam');\n  document.getElementById('pd-validate').addEventListener('click', ()=>{\n    const val = editor.value.trim();\n    const verdict = document.getElementById('pd-verdict');\n    const pattern = /^Allow\\s+(group|dynamic-group|any-user)\\s+[\\w'-]+(-[\\w']+)*\\s+to\\s+(inspect|read|use|manage)\\s+[\\w-]+(-family)?\\s+in\\s+(compartment|tenancy)(\\s+[\\w-]+)?(\\s+where\\s+.+)?$/i;\n    if(pattern.test(val)){\n      verdict.className='policy-verdict ok';\n      let note = '\u2713 Valid syntax.';\n      if(/manage all-resources/i.test(val)) note += ' \u26a0 Consider scoping to specific resource-families instead of all-resources for tighter least-privilege.';\n      verdict.textContent = note;\n    } else {\n      verdict.className='policy-verdict bad';\n      verdict.textContent = '\u2717 Syntax issue \u2014 expected form: Allow <subject> to <verb> <resource> in <location>';\n    }\n  });\n}\n\n/* ---------- tagging strategy ---------- */\nfunction initTaggingStrategy(){\n  const wrap = document.getElementById('tag-namespace-rows'); if(!wrap) return;\n  const dims = ['CostCenter','Department','Environment','Owner','Project','Lifecycle'];\n  wrap.innerHTML = dims.map(d=>`<div class=\"tag-namespace-row\"><span class=\"tag-pill\">Enterprise.${d}</span><input class=\"mini-input\" placeholder=\"example value for ${d}\" style=\"flex:1;\"></div>`).join('');\n  document.getElementById('tag-validate').addEventListener('click', ()=>{\n    const inputs = wrap.querySelectorAll('input');\n    const filled = [...inputs].filter(i=>i.value.trim()).length;\n    const result = document.getElementById('tag-validate-result');\n    if(filled===dims.length){ result.textContent = '\u2713 All 6 standard tag dimensions have example values \u2014 this namespace is ready to enforce via policy.'; result.style.color='var(--green)'; }\n    else { result.textContent = `\u26a0 ${filled}/${dims.length} dimensions filled \u2014 consider covering all standard dimensions before enforcing.`; result.style.color='var(--amber)'; }\n  });\n}\n\n;\n\n/* ---------- multi-tenancy designer ---------- */\nfunction initOrgMgmt(){ /* purely informational section, no widget */ }\nfunction initMultiTenancy(){}\ndocument.addEventListener('DOMContentLoaded', ()=>{\n  const addBtn = document.getElementById('org-child-add'); if(!addBtn) return;\n  let children = ['Finance','Engineering'];\n  const row = document.getElementById('org-children-row');\n  function render(){ row.innerHTML = children.map(c=>`<div class=\"org-child-box\">\ud83c\udfe2 ${c}</div>`).join(''); }\n  addBtn.addEventListener('click', ()=>{\n    const name = document.getElementById('org-child-name').value.trim(); if(!name) return;\n    children.push(name); document.getElementById('org-child-name').value=''; render();\n  });\n  render();\n});\n\n/* ---------- landing zone builder ---------- */\nfunction initLandingZone(){\n  const wrap = document.getElementById('lz-layers'); if(!wrap) return;\n  const layers = ['Identity Baseline (Groups, Policies, MFA)','Network Baseline (Hub VCN, Security Zones)','Logging &amp; Audit Baseline','Security Baseline (Cloud Guard, Vault)','Cost Baseline (Budgets, Tagging)'];\n  wrap.innerHTML = layers.map((l,i)=>`<div class=\"lz-layer-row\" data-i=\"${i}\"><span>${l}</span><span class=\"lz-status pending\">Not Configured</span></div>`).join('') + '<button class=\"chip-btn active mt-lg\" id=\"lz-configure-next\">Configure next layer</button>';\n  let configured = 0;\n  document.getElementById('lz-configure-next').addEventListener('click', ()=>{\n    const rows = wrap.querySelectorAll('.lz-layer-row');\n    if(configured < rows.length){\n      rows[configured].querySelector('.lz-status').className='lz-status configured';\n      rows[configured].querySelector('.lz-status').textContent='Configured';\n      configured++;\n    }\n  });\n}\n\n;\n\n/* ---------- cost analysis dashboard ---------- */\nfunction initCostAnalysis10(){\n  const pieCanvas = document.getElementById('deptPieChart'); if(!pieCanvas) return;\n  const pctx = pieCanvas.getContext('2d');\n  const depts = [['Engineering',76600,'#ff5a3c'],['Finance',30200,'#4f8cff'],['Operations',42100,'#e8a33d'],['Marketing',18400,'#3ec28f'],['HR',15100,'#9096a2']];\n  const w = pieCanvas.width=200, h = pieCanvas.height=200;\n  const total = depts.reduce((a,d)=>a+d[1],0); let start=-Math.PI/2;\n  depts.forEach(([name,val,color])=>{\n    const angle=(val/total)*Math.PI*2;\n    pctx.beginPath(); pctx.moveTo(w/2,h/2); pctx.arc(w/2,h/2,90,start,start+angle); pctx.closePath(); pctx.fillStyle=color; pctx.fill();\n    start+=angle;\n  });\n  document.getElementById('dept-pie-legend').innerHTML = depts.map(([n,v,c])=>`<div><span class=\"sw\" style=\"background:${c}\"></span>${n} \u2014 $${v.toLocaleString()}</div>`).join('');\n\n  const trendCanvas = document.getElementById('trend10Chart'); const tctx = trendCanvas.getContext('2d');\n  const tw = trendCanvas.width = trendCanvas.clientWidth||400, th = trendCanvas.height=200;\n  const months = [148000,155000,162000,171000,176000,182400];\n  const max = Math.max(...months);\n  tctx.beginPath();\n  months.forEach((v,i)=>{ const x=(i/(months.length-1))*(tw-20)+10; const y=th-20-(v/max)*(th-40); if(i===0) tctx.moveTo(x,y); else tctx.lineTo(x,y); });\n  tctx.strokeStyle='#ff5a3c'; tctx.lineWidth=2; tctx.stroke();\n}\n\n/* ---------- right sizing ---------- */\nfunction initRightSizing10(){\n  const shapes = document.querySelectorAll('[data-rs10]'); if(!shapes.length) return;\n  const savings = document.getElementById('rs10-savings');\n  const info = {\n    over: '\ud83d\udcc9 Advisor: downsize analytics-vm-03 from 16 OCPU to 4 OCPU based on 7% average utilization. Estimated savings: <strong style=\"color:var(--green);\">~$1,840/month</strong>.',\n    auto: '\ud83d\udcc8 Advisor: replace the fixed 6-instance cluster with an Instance Pool + Autoscaling (2-8 instances based on load). Estimated savings: <strong style=\"color:var(--green);\">~$2,100/month</strong> during off-peak hours.'\n  };\n  shapes.forEach(s=> s.addEventListener('click', ()=>{ shapes.forEach(x=>x.classList.remove('selected')); s.classList.add('selected'); savings.style.display='block'; savings.innerHTML = info[s.dataset.rs10]; }));\n}\n\n/* ---------- idle resource detector ---------- */\nfunction initIdleDetector(){\n  const wrap = document.getElementById('idle-list'); if(!wrap) return;\n  let items = [\n    {name:'Stopped instance: batch-vm-old', cost:620},\n    {name:'Unattached volume: vol-orphan-04 (200GB)', cost:340},\n    {name:'Unused Load Balancer: staging-lb-legacy', cost:180},\n    {name:'Unattached Reserved Public IP \u00d74', cost:60},\n    {name:'Empty bucket with lifecycle misconfig: old-logs', cost:3060},\n  ];\n  function total(){ return items.filter(i=>!i.cleaned).reduce((a,i)=>a+i.cost,0); }\n  function render(){\n    wrap.innerHTML = items.map((i,idx)=>`<div class=\"idle-item ${i.cleaned?'cleaned':''}\"><span>${i.name}</span><span>$${i.cost}/mo ${i.cleaned?'':'<button class=\\\"chip-btn\\\" data-clean=\\\"'+idx+'\\\" style=\\\"margin-left:10px;\\\">Clean up</button>'}</span></div>`).join('');\n    document.getElementById('idle-total').textContent = '$'+total().toLocaleString();\n  }\n  wrap.addEventListener('click', e=>{ if(e.target.dataset.clean!==undefined){ items[e.target.dataset.clean].cleaned=true; render(); } });\n  render();\n}\n\n/* ---------- commitment discounts ---------- */\nfunction initCommitment(){\n  const slider = document.getElementById('commit-slider'); if(!slider) return;\n  function render(){\n    const val = parseInt(slider.value);\n    document.getElementById('commit-val').textContent = val+'%';\n    const reco = document.getElementById('commit-reco');\n    if(val>=60){ reco.textContent = '\u2713 With a stable baseline this high, a 1-3 year commitment on that baseline portion could realistically save 20-40% versus Pay As You Go.'; reco.style.color='var(--green)'; }\n    else if(val>=30){ reco.textContent = '\u26a0 A moderate baseline \u2014 consider committing just that stable portion, keeping the volatile remainder on-demand.'; reco.style.color='var(--amber)'; }\n    else { reco.textContent = '\u2717 Too unpredictable for meaningful commitment discounts right now \u2014 stay on Pay As You Go until usage stabilizes.'; reco.style.color='var(--red-bright)'; }\n  }\n  slider.addEventListener('input', render); render();\n}\n\n;\n\n/* ---------- security gap analyzer ---------- */\nfunction initSecurityGap(){\n  const wrap = document.getElementById('secgap-panel'); if(!wrap) return;\n  const findings = [\n    ['Public bucket detected: \"invoices-archive\"', 'high'],\n    ['SSH open to 0.0.0.0/0 on 3 instances', 'high'],\n    ['Policy grants \"manage all-resources\" to Contractors group', 'high'],\n    ['MFA not enforced for 4 administrative users', 'medium'],\n    ['2 API keys older than 180 days without rotation', 'medium'],\n    ['Logging disabled on Finance compartment', 'low'],\n  ];\n  wrap.innerHTML = findings.map(([f,sev])=>`<div class=\"gap-item\"><span>${f}</span><span class=\"gap-severity priority-${sev==='high'?'high':sev==='medium'?'med':'low'}\">${sev}</span></div>`).join('');\n}\n\n/* ---------- remediation planner ---------- */\nfunction initRemediation(){\n  const wrap = document.getElementById('remediation-list'); if(!wrap) return;\n  const items = ['Remove public access from \"invoices-archive\" bucket','Restrict SSH ingress to known IP ranges','Scope Contractors policy to specific resource-families','Enforce MFA for all administrative users','Rotate API keys older than 180 days','Enable logging on Finance compartment'];\n  let score = 55;\n  const ring = document.getElementById('remediation-ring'); const val = document.getElementById('remediation-score-val');\n  wrap.innerHTML = items.map((t,i)=>`<div class=\"gap-item\" data-i=\"${i}\"><span>${t}</span><button class=\"chip-btn active\" data-fixidx=\"${i}\">Fix</button></div>`).join('');\n  wrap.addEventListener('click', e=>{\n    if(e.target.dataset.fixidx!==undefined){\n      const row = e.target.closest('.gap-item');\n      if(row.classList.contains('fixed')) return;\n      row.classList.add('fixed'); e.target.textContent='Fixed \u2713'; e.target.disabled=true;\n      score = Math.min(100, score + Math.floor(Math.random()*6)+6);\n      ring.style.setProperty('--s', score); val.textContent = score;\n    }\n  });\n}\n\n/* ---------- patch management & backup validation ---------- */\nfunction initPatchBackup(){\n  const btn = document.getElementById('patch-schedule'); if(!btn) return;\n  btn.addEventListener('click', ()=>{ document.getElementById('patch-window').textContent = 'Sat 02:00-04:00 UTC'; });\n  document.getElementById('backup-restore-test').addEventListener('click', ()=>{\n    const log = document.getElementById('backup-restore-log');\n    const lines = ['Locating latest backup for db-vol-01...','Provisioning test volume from backup...','Attaching test volume to sandbox instance...','Mounting filesystem...','Verifying data integrity checksum...','\u2713 Restore validated successfully \u2014 RPO confirmed at 4 hours.'];\n    log.textContent='';\n    lines.forEach((l,i)=> setTimeout(()=>{ log.textContent+=l+'\\n'; log.scrollTop=log.scrollHeight; }, i*400));\n  });\n}\n\n/* ---------- compliance matrix ---------- */\nfunction initCompliance10(){\n  const cards = document.querySelectorAll('#compliance10-grid .compliance-card'); if(!cards.length) return;\n  const detail = document.getElementById('compliance10-detail');\n  const info = {\n    iso: 'ISO 27001: ISMS standard \u2014 maps to compartment structure, IAM policies, and continuous Cloud Guard monitoring.',\n    soc2: 'SOC 2: security/availability/confidentiality controls \u2014 Vault, Audit logging, and Monitoring/Alarms are common evidence sources.',\n    pci: 'PCI DSS: cardholder data protection \u2014 Vault encryption, network segmentation via Security Zones, and access logging are core controls.',\n    hipaa: 'HIPAA: PHI protection \u2014 HSM-backed Vault keys, audit trails, and strict IAM least-privilege map directly to technical safeguards.',\n    gdpr: 'GDPR: EU personal data protection \u2014 data residency (region choice), encryption, and breach-notification-ready audit logs.',\n    nist: 'NIST 800-53/CSF: a control catalog many public-sector workloads must map every OCI control back to.',\n    cis: 'CIS Benchmarks: concrete hardening baselines (e.g. no public buckets, MFA required) \u2014 Security Advisor findings map almost 1:1 to CIS controls.'\n  };\n  cards.forEach(c=> c.addEventListener('click', ()=> detail.textContent = info[c.dataset.c10]));\n}\n\n/* ---------- audit readiness ---------- */\nfunction initAuditReadiness(){\n  const wrap = document.getElementById('audit-readiness-list'); if(!wrap) return;\n  const items = ['Encryption at rest verified on all storage','Centralized logging covers all compartments','Monitoring alarms configured for critical services','Access review completed in the last 90 days','All fleets show current patch status','Backup restore test validated in the last quarter'];\n  wrap.innerHTML = items.map((t,i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div class=\"lab-title\">${t}</div></div>`).join('');\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=> item.classList.toggle('done')));\n}\n\n/* ---------- compliance report generator ---------- */\nfunction initComplianceReport(){\n  const btn = document.getElementById('compliance-report-generate'); if(!btn) return;\n  btn.addEventListener('click', ()=>{\n    const checklist = document.querySelectorAll('#audit-readiness-list .lab-item');\n    const done = document.querySelectorAll('#audit-readiness-list .lab-item.done').length;\n    const out = document.getElementById('compliance-report-out'); out.style.display='block';\n    out.textContent = `COMPLIANCE READINESS REPORT\nGenerated: ${new Date().toLocaleDateString()}\n\nAudit Readiness: ${done}/${checklist.length || 6} items confirmed\n\nFrameworks in scope: ISO 27001, SOC 2, PCI DSS\nOverall posture: ${done>=5?'READY':'NEEDS ATTENTION'}\n\nRecommendation: ${done>=5 ? 'Environment appears audit-ready. Schedule the formal external audit.' : 'Close remaining Audit Readiness gaps before scheduling a formal audit.'}`;\n  });\n}\n\n;\n\n/* ---------- case study component detail ---------- */\nfunction initCaseStudy(){\n  const comps = document.querySelectorAll('#casestudy-grid .studio-component'); if(!comps.length) return;\n  const detail = document.getElementById('casestudy-detail');\n  const info = {\n    iam: 'IAM & Policies: least-privilege access separating Dev/Ops/DBA roles, with MFA enforced for anyone touching Production.',\n    terraform: 'Terraform: the entire VCN, compute fleet, and storage are defined as code \u2014 every change is reviewed and version-controlled.',\n    vcn: 'VCN & Subnets: public subnet for the load balancer, private subnets for app and database tiers.',\n    compute: 'Compute: an autoscaling instance pool for the app tier, sized from real traffic patterns.',\n    block: 'Block Storage: high-IOPS volumes for the database tier, backed up nightly.',\n    object: 'Object Storage: transaction logs and statements, lifecycle-managed to Archive after 90 days.',\n    vault: 'Vault: database credentials and API keys, HSM-protected given the regulatory requirements of banking.',\n    lb: 'Load Balancer: TLS termination, health checks on a real app-readiness endpoint, WAF rules for common attack patterns.',\n    monitoring: 'Monitoring: alarms on latency, error rate, and backend health \u2014 paging on-call before customers notice.',\n    logging: 'Logging: centralized audit and flow logs, retained per the bank\\'s compliance requirements.',\n    cloudguard: 'Cloud Guard: tenancy-wide detection for misconfigurations, with auto-remediation for public bucket exposure.',\n    backup: 'Backup & DR: cross-region Vault replication and a tested failover runbook \u2014 validated quarterly, not just documented.'\n  };\n  comps.forEach(c=> c.addEventListener('click', ()=> detail.textContent = info[c.dataset.cs]));\n}\n\n/* ---------- architecture design studio ---------- */\nfunction initArchStudio(){\n  const comps = document.querySelectorAll('#studio-components .studio-component'); if(!comps.length) return;\n  let added = new Set();\n  comps.forEach(c=> c.addEventListener('click', ()=>{ c.classList.toggle('added'); if(c.classList.contains('added')) added.add(c.dataset.comp); else added.delete(c.dataset.comp); }));\n  document.getElementById('studio-score').addEventListener('click', ()=>{\n    const total = comps.length;\n    const score = Math.round((added.size/total)*100);\n    document.getElementById('studio-ring').style.setProperty('--dscore', score);\n    document.getElementById('studio-score-val').textContent = score;\n    const missing = [...comps].filter(c=>!added.has(c.dataset.comp)).map(c=>c.textContent);\n    const fb = document.getElementById('studio-feedback');\n    if(missing.length===0) fb.textContent = '\u2713 Complete architecture \u2014 every layer from compartments to DR is represented.';\n    else fb.innerHTML = `Missing: ${missing.join(', ')}. A production banking platform needs every one of these layers.`;\n  });\n}\n\n/* ---------- operations center ---------- */\nfunction initOpsCenter(){\n  const tabs = document.querySelectorAll('#opscenter-tabs .chip-btn'); if(!tabs.length) return;\n  const panel = document.getElementById('opscenter-panel');\n  const info = {\n    deploy: 'Deployment: Terraform plan reviewed and applied via Resource Manager \u2014 zero manual console changes in Production.',\n    monitor: 'Monitoring: all critical services have alarms wired to the on-call rotation; dashboards show real-time health.',\n    incident: 'Incident Response: the 6-step methodology from Day 8 applies here too \u2014 Identify, Isolate, Diagnose, Resolve, Validate, Prevent.',\n    scale: 'Scaling: the app tier autoscaling policy responds to CPU and request-count metrics, tested under simulated load.',\n    cost: 'Cost Review: monthly FinOps review catches idle resources and right-sizing opportunities before they compound.',\n    security: 'Security Review: Cloud Guard findings and Security Advisor score are reviewed weekly, not just during audits.',\n    backup: 'Backup: automated nightly backups with a tested, not just configured, restore path.',\n    dr: 'DR Test: quarterly failover to the replica region, with an actual traffic cutover \u2014 not a tabletop exercise.',\n    audit: 'Compliance Audit: continuous evidence collection (logs, configs) means the annual audit is a formality, not a scramble.'\n  };\n  tabs.forEach(t=>{\n    t.addEventListener('click', ()=>{\n      tabs.forEach(x=>x.classList.remove('active')); t.classList.add('active'); t.classList.add('done');\n      panel.textContent = info[t.dataset.ops];\n    });\n  });\n  tabs[0].click();\n}\n\n;\n\n/* ---------- console simulator 10 ---------- */\nfunction initConsoleSim10(){\n  const nav = document.querySelectorAll('.console-nav div[data-panel10]'); if(!nav.length) return;\n  nav.forEach(item=>{\n    item.addEventListener('click', ()=>{\n      nav.forEach(n=>n.classList.remove('active')); item.classList.add('active');\n      document.querySelectorAll('.console-panel10').forEach(p=>p.style.display='none');\n      document.getElementById('panel10-'+item.dataset.panel10).style.display='';\n    });\n  });\n}\n\n/* ---------- operations health dashboard ---------- */\nfunction initOpsHealth(){\n  const wrap = document.getElementById('opshealth-grid'); if(!wrap) return;\n  const metrics = [\n    ['Infrastructure Health','98.2%',false], ['Application Health','96.5%',false],\n    ['Open Incidents','1',true], ['Budget Status','89% used',false],\n    ['Avg Latency','142ms',false], ['Availability (30d)','99.95%',false],\n    ['Risk Score','Medium',true], ['Compliance Status','Ready',false],\n  ];\n  wrap.innerHTML = metrics.map(([l,v,alert])=>`<div class=\"metric-card ${alert?'alert':''}\"><div class=\"m-label\">${l}</div><div class=\"m-val\">${v}</div></div>`).join('');\n}\n\n;\n\n/* ---------- comprehensive enterprise lab ---------- */\nfunction initEnterpriseLab(){\n  const wrap = document.getElementById('enterprise-lab-grid'); if(!wrap) return;\n  const items = ['Compartments','IAM Policies','VCN & Subnets','Route Tables','Security Lists','NSGs','Compute Instances','Block Storage','Object Storage','Vault & Keys','Monitoring & Alarms','Logging','Cloud Guard','Budgets','Terraform Stack','Load Balancer'];\n  wrap.innerHTML = items.map((t,i)=>`<div class=\"lab-item\" data-i=\"${i}\"><div class=\"lab-check\">\u2713</div><div class=\"lab-title\">${t}</div></div>`).join('');\n  function updateProgress(){ document.getElementById('enterprise-lab-progress').textContent = `${wrap.querySelectorAll('.lab-item.done').length} / ${items.length} complete`; }\n  wrap.querySelectorAll('.lab-item').forEach(item=> item.addEventListener('click', ()=>{ item.classList.toggle('done'); updateProgress(); updateBadge10(); }));\n  updateProgress();\n}\n\n/* ---------- enterprise troubleshooting ---------- */\nfunction initEnterpriseTrouble(){\n  const btns = document.querySelectorAll('#ent-trouble-btns .chip-btn'); if(!btns.length) return;\n  const panel = document.getElementById('ent-trouble-panel');\n  const cases = {\n    security: {err:'Cloud Guard: \"Compute instance has a publicly accessible database port open.\"', fix:'Draw on Day 6 (Security Zones would have blocked this) and Day 2 (Cloud Guard responder to auto-remediate): restrict the Security List/NSG immediately, then add a Security Zone to prevent recurrence.'},\n    budget: {err:'Budget alert: Production compartment at 140% of monthly budget.', fix:'Use the Idle Resource Detector and Cost Analysis dashboard from this module to find the spike\\'s source, then apply Right Sizing recommendations.'},\n    network: {err:'App tier can\\'t reach the database tier after a route table change.', fix:'Apply the Day 5/Day 8 methodology: check route tables for longest-prefix-match issues, then Security Lists/NSGs.'},\n    terraform: {err:'terraform apply fails: \"Error: 400-InvalidParameter, CIDR block overlaps existing subnet.\"', fix:'A classic state drift issue \u2014 someone made a manual Console change. Fix: terraform plan to see drift, then reconcile state before reapplying.'},\n    vault: {err:'Application error: \"NotAuthorizedOrNotFound\" calling Vault GetSecretBundle.', fix:'From Day 6: check the dynamic group\\'s matching rule includes this instance, and the IAM policy grants it access to the secret.'},\n    monitoring: {err:'Alarms configured but nobody was paged during the last incident.', fix:'Check the alarm\\'s notification topic subscription \u2014 a common gap is a correctly-firing alarm with a broken or unconfirmed subscription.'},\n    lb: {err:'Load Balancer shows all backends healthy, but customers report 502s intermittently.', fix:'From Day 8: check for a backend crashing mid-request under load \u2014 health checks passing doesn\\'t guarantee every request succeeds under real traffic.'},\n    dr: {err:'DR failover test to the replica region failed \u2014 application couldn\\'t start.', fix:'Likely a configuration drift between primary and replica (e.g. the replica Vault wasn\\'t granted the same IAM policies). This is exactly why DR tests must be run for real, not just documented.'}\n  };\n  function render(key){ const c = cases[key]; panel.innerHTML = `<p class=\"mono\" style=\"color:var(--red-bright);\">${c.err}</p><p class=\"small mt-lg\" style=\"color:var(--green);\">\u2713 ${c.fix}</p>`; }\n  btns.forEach(b=> b.addEventListener('click', ()=>{ btns.forEach(x=>x.classList.remove('active')); b.classList.add('active'); render(b.dataset.etcase); }));\n  render('security');\n}\n\n;\n\n/* ---------- flashcards 10 ---------- */\nfunction initFlashcards10(){\n  const wrap = document.getElementById('flash-wrap10'); if(!wrap) return;\n  const cards = [\n    ['Compartment vs Tag','Compartment = access boundary; Tag = classification/cost label'],\n    ['Quota vs Limit','Quota = self-imposed; Limit = provider ceiling (needs support request)'],\n    ['Security Zone vs Cloud Guard','Zone blocks at request time; Guard detects+responds after'],\n    ['Organization Management','Links tenancies for billing, not IAM'],\n    ['Right sizing basis','Real utilization metrics, never guesses'],\n    ['Idle resources','The fastest, lowest-risk cost savings available'],\n    ['Commitment discount tradeoff','Lower unit cost in exchange for reduced flexibility'],\n    ['Security posture score','A composite of IAM + Vault + Cloud Guard + Logging'],\n    ['CIS Benchmarks','Concrete hardening baselines, map ~1:1 to Advisor findings'],\n    ['Terraform vs Ansible','Terraform provisions; Ansible configures'],\n    ['DR test validity','Only a real failover test counts \u2014 documentation alone doesn\\'t'],\n    ['Executive maturity score','Rolls up Governance + Security + Cost + Compliance + Availability + Ops'],\n  ];\n  wrap.innerHTML = cards.map(([f,b])=>`<div class=\"flashcard\"><div class=\"fc-inner\"><div class=\"fc-face fc-front\">${f}</div><div class=\"fc-face fc-back\">${b}</div></div></div>`).join('');\n  wrap.querySelectorAll('.flashcard').forEach(fc=> fc.addEventListener('click', ()=> fc.classList.toggle('flipped')));\n}\n\n/* ---------- mock exam (20 questions, domain-tracked) ---------- */\nfunction initQuiz10(){\n  const wrap = document.getElementById('quiz-wrap10'); if(!wrap) return;\n  const Q = [\n    {d:'Governance', q:'A policy grants \"manage all-resources\" to a contractor group. This violates:', o:['Defense in depth','Least privilege','Tagging strategy','Budget governance'], c:1, e:'Granting broad access beyond what\\'s needed directly violates least privilege.'},\n    {d:'Governance', q:'What differentiates a Quota from a Service Limit?', o:['Quotas are set by Oracle only','Quotas are self-imposed within existing Limits, which are provider ceilings', 'They are identical', 'Limits are set per-user'], c:1, e:'Quotas are admin-controlled caps within the Limits Oracle enforces.'},\n    {d:'Governance', q:'Organization Management primarily provides:', o:['Shared IAM across tenancies','Centralized billing across linked tenancies while keeping IAM separate', 'Automatic policy replication', 'Free compute credits'], c:1, e:'It consolidates billing/governance oversight without merging IAM.'},\n    {d:'Org Management', q:'A Landing Zone is best described as:', o:['A single VCN','A pre-built, compliant baseline environment new workloads deploy into', 'A billing report', 'A type of compute shape'], c:1, e:'Landing Zones give every new workload a secure, governed starting point.'},\n    {d:'Cost', q:'The fastest, lowest-risk cost optimization action is usually:', o:['Buying a 3-year commitment immediately','Cleaning up idle/unused resources', 'Migrating to a different cloud', 'Disabling monitoring'], c:1, e:'Idle resources are pure waste with essentially zero risk to remove.'},\n    {d:'Cost', q:'Right-sizing recommendations should be based on:', o:['Guesswork','Actual observed utilization metrics', 'The most expensive shape available', 'Random sampling'], c:1, e:'Utilization data is the only reliable basis for right-sizing.'},\n    {d:'Cost', q:'A 1-3 year commitment discount is the best fit for:', o:['Highly unpredictable, spiky workloads','A stable, predictable baseline of usage', 'One-time batch jobs', 'Disaster recovery standby only'], c:1, e:'Commitments trade flexibility for discount \u2014 best applied to your predictable floor of usage.'},\n    {d:'Security', q:'A composite Security Posture score typically rolls up:', o:['Only firewall rules','IAM, Vault/Encryption, Cloud Guard coverage, and Logging/Audit together', 'Only the number of users', 'Only budget data'], c:1, e:'Security posture spans identity, encryption, detection, and audit trail \u2014 not a single control.'},\n    {d:'Security', q:'A Security Gap Analyzer finding \"no MFA enforced\" is best remediated by:', o:['Ignoring it if no breach has happened yet','Requiring MFA for administrative users', 'Deleting the affected accounts', 'Disabling logging'], c:1, e:'MFA enforcement directly closes that specific gap.'},\n    {d:'Security', q:'A validated backup restore test differs from a backup policy because:', o:['They are the same thing','A restore test proves data can actually be recovered, not just that a backup file exists', 'Restore tests are unnecessary if backups are automated', 'Backup policies replace the need for encryption'], c:1, e:'\"We have backups\" and \"we\\'ve proven the backups work\" are very different guarantees.'},\n    {d:'Compliance', q:'CIS Benchmarks are best described as:', o:['A legal contract','Concrete technical hardening baselines that map closely to Security Advisor findings', 'A billing framework', 'An OCI-specific certification'], c:1, e:'CIS Benchmarks translate directly into checkable technical controls.'},\n    {d:'Compliance', q:'For a healthcare workload handling PHI, which framework is most directly relevant?', o:['PCI DSS only','HIPAA', 'CIS only', 'None apply to cloud'], c:1, e:'HIPAA specifically governs protected health information.'},\n    {d:'Compliance', q:'An \"audit-ready\" environment should have all of the following EXCEPT:', o:['Encryption at rest verified','Centralized logging across compartments', 'Undocumented manual exceptions to policy', 'A recent access review'], c:2, e:'Undocumented exceptions are exactly what audits flag \u2014 everything should be documented and justified.'},\n    {d:'Case Study', q:'In the banking platform case study, why is the database tier placed in a private subnet?', o:['Private subnets are cheaper','It has no legitimate need for direct internet exposure, reducing attack surface', 'Public subnets don\\'t support databases', 'It improves query performance'], c:1, e:'Removing unnecessary internet exposure is a core defense-in-depth principle.'},\n    {d:'Case Study', q:'Why does the case study use HSM-protected Vault keys specifically?', o:['It is the cheapest option','Banking/financial compliance typically requires hardware-backed key protection', 'HSM is required for all OCI tenancies', 'It has no functional difference from software-protected keys'], c:1, e:'Regulated industries like banking commonly require FIPS 140-2 Level 3 hardware-backed keys.'},\n    {d:'Operations', q:'In Operations Center, what makes a DR test meaningful?', o:['Documenting the DR plan in a wiki','Actually performing a real failover to the replica region', 'Having a backup policy configured', 'Scheduling it but never executing'], c:1, e:'Only an executed failover proves DR actually works end to end.'},\n    {d:'Operations', q:'A load balancer shows all backends healthy, but customers still see intermittent 502s. What does this suggest?', o:['The health check itself is broken and lying','Backends can pass periodic health checks yet still fail under real request load', 'The load balancer is misconfigured entirely', '502s are unrelated to backend health'], c:1, e:'Health checks sample periodically \u2014 they don\\'t guarantee every real request succeeds under load.'},\n    {d:'Operations', q:'A Terraform apply fails due to a CIDR overlap that wasn\\'t in the last known plan. Most likely cause?', o:['A bug in Terraform itself','Manual Console changes caused state drift from the actual infrastructure', 'Terraform doesn\\'t support VCNs', 'The internet connection failed'], c:1, e:'Out-of-band manual changes are the most common cause of Terraform state drift.'},\n    {d:'Capstone', q:'An Executive Dashboard\\'s \"Overall Cloud Maturity Score\" is best understood as:', o:['A single arbitrary number with no basis','A composite roll-up of Governance, Security, Cost, Compliance, Availability, and Operations scores', 'Only a security score', 'A number set manually by leadership'], c:1, e:'It deliberately blends every operational dimension covered across the course into one number.'},\n    {d:'Capstone', q:'When multiple root causes are possible in an enterprise incident, the right approach is:', o:['Guess the most likely one and fix it immediately','Apply structured methodology (Identify \u2192 Isolate \u2192 Diagnose) to rule causes in or out systematically', 'Restart everything at once', 'Wait for the issue to resolve itself'], c:1, e:'Structured diagnosis avoids wasted effort and missed root causes \u2014 the same 6-step methodology applies at enterprise scale.'},\n  ];\n  state.quizTotal = Q.length;\n  const domains = [...new Set(Q.map(q=>q.d))];\n  const domainStats = {}; domains.forEach(d=> domainStats[d] = {correct:0, total:0});\n\n  function renderDomainBars(){\n    const wrap2 = document.getElementById('domain-performance');\n    wrap2.innerHTML = '<h4 style=\"margin-bottom:12px;\">Domain-wise Performance</h4>' + domains.map(d=>{\n      const s = domainStats[d]; const pct = s.total ? Math.round((s.correct/s.total)*100) : 0;\n      return `<div class=\"domain-bar-row\"><span class=\"domain-name\">${d}</span><div class=\"domain-bar-track\"><div class=\"domain-bar-fill\" style=\"width:${pct}%;\"></div></div><span class=\"small\">${s.correct}/${s.total}</span></div>`;\n    }).join('');\n  }\n  renderDomainBars();\n\n  wrap.innerHTML = Q.map((item,qi)=>`\n    <div class=\"quiz-q\" id=\"quiz10-${qi}\">\n      <div class=\"qtext\"><span class=\"tag\" style=\"margin-right:8px;\">${item.d}</span>${qi+1}. ${item.q}</div>\n      <div class=\"quiz-opts\">${item.o.map((opt,oi)=>`<label class=\"quiz-opt\"><input type=\"radio\" name=\"q10-${qi}\" value=\"${oi}\"> ${opt}</label>`).join('')}</div>\n      <div class=\"quiz-explain\">${item.e}</div>\n    </div>`).join('');\n  wrap.querySelectorAll('.quiz-q').forEach((qEl, qi)=>{\n    qEl.addEventListener('change', e=>{\n      if(qEl.classList.contains('answered')) return;\n      qEl.classList.add('answered');\n      const chosen = parseInt(e.target.value);\n      qEl.querySelectorAll('.quiz-opt').forEach((o,oi)=>{ if(oi===Q[qi].c) o.classList.add('correct'); else if(oi===chosen) o.classList.add('incorrect'); });\n      state.quizAnswered++;\n      const d = Q[qi].d; domainStats[d].total++;\n      if(chosen===Q[qi].c){ state.quizScore++; domainStats[d].correct++; }\n      renderDomainBars();\n      document.getElementById('score-chip-val').textContent = `${state.quizScore} / ${state.quizAnswered}`;\n      document.getElementById('quiz-final-score10').textContent = `${state.quizScore} / ${Q.length}`;\n      document.getElementById('cert-score-display10').textContent = `${state.quizScore}/${Q.length}`;\n      updateBadge10();\n    });\n  });\n}\n\n/* ---------- badge / certificate 10 ---------- */\nfunction updateBadge10(){\n  const scrollPct = window.__lastScrollPct10 || 0;\n  const quizPct = state.quizTotal ? (state.quizAnswered/state.quizTotal)*100 : 0;\n  const combined = Math.round(scrollPct*0.5 + quizPct*0.5);\n  const circle = document.getElementById('badge-circle10'); if(!circle) return;\n  circle.style.setProperty('--pct', (combined*3.6)+'deg');\n  document.getElementById('badge-pct10').textContent = combined+'%';\n  const title = document.getElementById('badge-title10'); const sub = document.getElementById('badge-sub10');\n  if(combined>=95){ title.textContent='\ud83c\udfc6 Capstone Complete'; sub.textContent='Certificate preview unlocked below \u2014 congratulations on completing the course.'; }\n  else if(combined>=50){ title.textContent='\ud83d\udfe0 Halfway there'; sub.textContent='Keep going through the remaining sections and the mock exam.'; }\n  else { title.textContent='Keep going'; sub.textContent='Complete every section and the mock exam to preview your capstone certificate.'; }\n  const d = new Date(); document.getElementById('cert-date-display10').textContent = d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});\n  const overallRing = document.getElementById('exec-overall-ring');\n  if(overallRing){ overallRing.style.setProperty('--s', combined); document.getElementById('exec-overall-val').textContent = combined; }\n}\n"};
